window.HS_SEED={"articles": [{"id": "a1000", "slug": "grace-on-the-bluff-offers-free-donated-items-to-hoover-commu", "title": "Grace on the Bluff offers free donated items to Hoover community", "dek": "Church on the Bluff will turn the traditional yard sale model into a community giveaway, offering donated items at no cost as part of its outreach efforts.", "section": "news", "subsection": "", "author": "Staff", "date": "2026-10-02T14:43:25", "image": "img/00.jpg", "caption": "Grace on the Bluff 2025", "credit": "Photo courtesy of Church on the Bluff", "status": "published", "body": [["p", "Church on the Bluff will host Grace on the Bluff on Saturday, Oct. 3, from 8-11 a.m. at the church in Hoover."], ["p", "In the event of rain, Grace on the Bluff will be held inside the church's fellowship hall."], ["p", "The event will operate much like a community yard sale, except everything will be free. Visitors are welcome to take something they need or an item they would simply enjoy. No purchases are required, and the church will not accept cash donations during the event."], ["p", "\"God's Grace is a gift freely given to us, and we want to reflect that generosity by giving freely to others,\" Pastor Tony Barber said. \"Everyone is welcome.\""], ["p", "Community members can also contribute items ahead of the giveaway. Donations will be accepted at the church's fellowship hall from 9-11 a.m. and 4-8 p.m. Thursday, Oct. 1, and Friday, Oct. 2. Heavy furniture will not be accepted."], ["p", "Church on the Bluff serves the Bluff Park and greater Hoover community through worship, fellowship and community outreach."], ["p", "The church is located at 2211 McGwier Drive. For more information, visit churchonthebluff.org/grace-on-the-bluff or call 205-822-3240."]], "source": "https://hooversun.com/news/grace-on-the-bluff-offers-free-donated-items-to-hoover-commu/", "placement": "", "views": 0}, {"id": "a1001", "slug": "football-friday-100226", "title": "Football Friday: Bucs at home, Jags on road", "dek": "High school football in Hoover continues Friday night.", "section": "sports", "subsection": "", "author": "Kyle Parmley", "date": "2026-10-02T11:53:00", "image": "img/01.jpg", "caption": "Under the Lights football gameday.", "credit": "", "status": "published", "body": [["p", "Friday night means gameday for the local high school football teams, and Under the Lights is back to cover Football Friday."], ["p", "Hoover and Spain Park are back in action Friday night, with Hoover hosting rival Thompson and Spain Park hitting the road to play unbeaten Prattville."], ["p", "For updates throughout Friday night and all season, follow sports editor Kyle Parmley on X (@KyleParmley) and the Under the Lights social media accounts (Facebook and X)."], ["p", "Be sure you're subscribed to the Under the Lights email newsletter, where you get the updated each weekend on the scores and news from the Friday night action. Subscribe at this link."], ["p", "Thank you to Southlake Orthopaedics for sponsoring our coverage of Hoover football this season."], ["h", "Hoover (3-3) vs. Thompson (5-0)"], ["li", "Date: Friday, Oct. 2"], ["li", "Time: 7 p.m."], ["li", "Location: Hoover Met"], ["p", "Last week: Hoover fell to Knoxville Catholic 20-17; Thompson had an open date."], ["p", "What to watch: Hoover let a fourth-quarter lead slip away on the final play against Knoxville Catholic, as a last-second Hail Mary gave the Bucs a tough loss to stomach. Hoover will look to rebound against one of its archrivals this week. Thompson, off an open date after a 62-7 win over Tuscaloosa County, has looked nearly unstoppable for much of the season so far, but Hoover has a penchant for playing its best against the Warriors."], ["p", "Last meeting: Hoover beat Thompson 33-30 in 2025. Hoover leads the all-time series with Thompson 26-9."], ["p", "Next week: Hoover travels to Vestavia Hills, while Thompson travels to Hewitt-Trussville."], ["h", "Spain Park (3-2) at Prattville (5-0)"], ["li", "Date: Friday, Oct. 2"], ["li", "Time: 7 p.m."], ["li", "Location: Stanley-Jensen Stadium, Prattville"], ["p", "Last week: Spain Park and Prattville each had an open date."], ["p", "What to watch: Spain Park had an open date to recover from a disappointing loss to Vestavia Hills two weeks ago. When the Jags have played at their top level, they have proven to be the type of team capable of competing with the top teams in the region, of which Prattville has proven to be. Prattville, off a bye after its blowout win over Hewitt-Trussville, is one of two unbeaten teams remaining in Class 6A, Region 3, along with Thompson."], ["p", "Last meeting: Spain Park beat Prattville 19-16 in 2013. Spain Park leads the series 2-1."], ["p", "Next week: Spain Park hosts Tuscaloosa County, while Prattville hosts Oak Mountain."]], "source": "https://hooversun.com/sports/football-friday-100226/", "placement": "", "views": 0}, {"id": "a1002", "slug": "taste-of-hoover-returns-oct-15-to-aldridge-gardens", "title": "Taste of Hoover returns Oct. 15 to Aldridge Gardens", "dek": "The 2026 Taste of Hoover returns Oct. 15 from 5 to 8 p.m. at Aldridge Gardens, with local restaurants, live music and a limited number of tickets.", "section": "news", "subsection": "", "author": "Kelli S. Hewett", "date": "2026-10-01T21:46:00", "image": "img/02.jpg", "caption": "Taste of Hoover is set for Thursday, Oct. 15, from 5 to 8 p.m. at Aldridge Gardens.", "credit": "Staff photos.", "status": "published", "body": [["p", "The 2026 Taste of Hoover will give residents a chance to sample the flavors of the city in one evening at Aldridge Gardens."], ["p", "The annual event is set for Thursday, Oct. 15, from 5 to 8 p.m. at the Gardens, located at 3530 Lorna Road."], ["p", "Guests can expect food and drink samplings from local restaurants and preferred caterers, live music and ambient lighting, all in an outdoor setting overlooking the gardens."], ["p", "Kristen Valentine, events coordinator for the City of Hoover, said the evening setting and location are a big part of the appeal."], ["p", "“Taste of Hoover offers a warm, festive atmosphere under beautiful string lights, surrounded by the natural beauty of Aldridge Gardens,” Valentine said. “Guests enjoy delicious local food, refreshing beverages, live music and easygoing conversation in a charming outdoor setting that feels like an elevated Southern garden party.”"], ["p", "A limited number of tickets are sold each year, and organizers say the event frequently sells out in advance. One ticket buys access to all participating food and beverage vendors."], ["p", "The event is designed as more than a typical food festival."], ["p", "“Taste of Hoover offers a unique opportunity for the community to come together in one place to experience the flavors that define our city,” Valentine said. “By showcasing a diverse collection of local restaurants and beverage providers, the event celebrates the people and the businesses that make Hoover special.”"], ["p", "Beyond the food and music, organizers say the event is an easy way for residents and visitors to experience a cross-section of the city’s dining scene in a single night."], ["p", "With local restaurants and preferred caterers setting up side by side, guests can move at their own pace, sample small bites, compare flavors and make notes on places they might want to visit later. For many attendees, it serves as both a social outing and a low-pressure way to discover new spots without committing to a full meal at each restaurant."], ["p", "Dozens of food and beverage vendors are set to participate, including Board in Birmingham, Grimaldi’s Pizza, Tacos de Azul at Brock’s Gap Brewing, Saw’s BBQ, East 59 Cafe, Michelle’s Chocolate Laboratory, Something Simple Coffee + Sips and more."], ["p", "“Guests love Taste of Hoover because it brings the community together in a fun, welcoming atmosphere,” Valentine said. “It’s a chance to connect with local people, discover new restaurants and try foods and drinks they may not have experienced before.”"], ["p", "Tickets are now on sale at aldridgegardens.com. General admission tickets are $50 for the public and $45 for Aldridge Gardens members. Parking and shuttle service are available from the Trader Joe’s parking lot in the Riverchase Shopping Center at the intersection of Highway 31 and Lorna Road. Free general admission to the gardens is suspended during event hours."]], "source": "https://hooversun.com/news/taste-of-hoover-returns-oct-15-to-aldridge-gardens/", "placement": "top", "views": 0}, {"id": "a1003", "slug": "hoover-business-happenings-october-2026", "title": "Hoover business happenings: October 2026", "dek": "See what's happening in the Hoover business community in October.", "section": "business", "subsection": "", "author": "Lauren H. Dowdle", "date": "2026-10-01T21:39:00", "image": "img/03.jpg", "caption": "goGLOW Hoover", "credit": "", "status": "published", "body": [["h", "Now Open"], ["p", "A spray tanning studio franchise, goGLOW Hoover, had its grand opening Aug. 15 at 4745 Chace Circle, Suite 109, in the Chace Lake area. Every airbrush tan is hand applied by a certified technician using their proprietary technique and custom-blended formula. The formula is custom blended for the customer’s skin tone and depth without UV damage or harsh ingredients. Owned by Kristen Adaraloye, the Hoover location is open Monday, Tuesday and Friday from 9 a.m. to 9 p.m., Wednesday and Thursday 9 a.m. to 10 p.m., and Saturday and Sunday 10 a.m. to 6 p.m."], ["p", "205-600-2103, goglow.co/hoover"], ["p", "The Painted Purple Turtle DIY craft workshop opened Aug. 29 at 3704 Lorna Road in Hoover’s River Oaks Village shopping center. The studio offers creative, hands-on crafts for social events, private parties, team-building events, subscription boxes and DIY kits. From their open studio to pick-a-project sessions, people can create projects using wood, resin, paint, sea glass and more. They are only open during scheduled social events, and people are invited to stop by for walk-ins, shopping or project pick-ups during those workshop times."], ["p", "256-870-9115, thepaintedpurpleturtle.com"], ["p", "Fifth Third Bank opened a new branch at 6602 Tattersall Lane in Hoover near Walk-On’s Sports Bistreaux off of U.S. 280. The 168-year-old company is based out of Cincinnati and entered the Alabama market in 2024, and there are also locations in Liberty Park and Vestavia Hills. The bank offers financial services for individuals, families, businesses and communities. The branch is open Monday through Thursday from 9 a.m. to 5 p.m., Friday 9 a.m. to 6 p.m. and Saturday 9 a.m. to noon."], ["p", "205-986-0189, 53.com"], ["p", "Diggin’ Depot Play Café opened at 2057 Old Montgomery Highway in the Legacy Park of Riverchase shopping center as an indoor play café for children ages 1 to 7. From construction vehicles and interactive play zones to its 40 tons of sand, Diggin’ Depot offers a place for children to dig, pour, build, scoop, and play with sand and toys. They are open Monday through Saturday from 8:30 a.m. to 5 p.m. and Sunday noon to 3 p.m. Diggin’ Depot is also open for private parties after 3 p.m. on Sunday."], ["p", "205-276-5524, diggindepot.com"], ["p", "Donna K Rheumatology and Infusion Services recently opened at 5190 Medford Drive, Suite 100, in The Shops at 150 near Jubilee Joe’s. They provide rheumatology consultations and ongoing care for autoimmune, inflammatory and musculoskeletal conditions. The clinic offers infusion services including biologic therapies for conditions like rheumatoid arthritis, gout and lupus, as well as wellness infusions. Dr. Donna K. Maneice has more than 30 years of medical experience with patients with rheumatic and autoimmune conditions, and she previously worked at a practice in Tuscaloosa. The clinic is open Monday through Thursday from 8 a.m. to 4 p.m. and Friday 8 a.m. to noon."], ["p", "205-800-8887, donnak.care"], ["h", "Relocations And Renovations"], ["p", "Whiskey Foxtrot relocated its Hoover location to 2801 John Hawkins Parkway near Tortugas Homemade Pizza. Previously located at 2341 John Hawkins Parkway in Lake Crest Plaza, Whiskey Foxtrot is known for its Wagyu beef burgers, craft beers, hot dogs and house-made sauces. Owned by brothers Ben and Zac Williams, the restaurant first opened in Hoover in 2021 and also has a location in Homewood. Whiskey Foxtrot is open Tuesday through Saturday from 11 a.m. to 9 p.m. and Sunday 11 a.m. to 8 p.m."], ["p", "205-536-6172, whiskeyfoxtrotbham.com"], ["h", "News And Accomplishments"], ["p", "Birmingham Orthodontics is distributing more than 7,000 oral hygiene kits to schools and community organizations across Birmingham through a back-to-school initiative. The program is designed to improve children’s oral health and ensure they have access to basic hygiene supplies. Each kit includes a toothbrush, fluoride toothpaste, dental floss and a reusable carrying case that can also be used as a pencil pouch. School nurses will distribute the kits to students who need access to basic oral hygiene supplies. The initiative is part of a large investment in oral hygiene supplies supporting schools and families across multiple states. Schools, PTOs, school nurses and youth-serving community organizations can request kits. Their Hoover location is at 5391 Magnolia Trace and is open Monday through Thursday from 8 a.m. to 5 p.m. and Friday 8 a.m. to 1 p.m."], ["p", "205-584-4030, bhamorthodontics.com"], ["h", "Personnel Moves"], ["p", "Matthew C. Anderson, a fellowship-trained hand and upper extremity surgeon and Birmingham native, joined OrthoAlabama Spine and Sports in September. He will see patients in Hoover at 118 Mars Hill Road, as well as in Trussville. Dr. Anderson specializes in comprehensive surgical and nonsurgical care of conditions affecting the hand, wrist and elbow, including arthritis, sports injuries, fracture care, overuse injuries, nerve repair, compressive neuropathies and other conditions. He earned his Doctor of Medicine degree from the University of Alabama at Birmingham Heersink School of Medicine, completed his residency at Prisma Health Upstate in Greenville, South Carolina, and did his fellowship training at the University of Alabama at Birmingham and American Sports Medicine Institute."], ["p", "205-228-7600, orthoalabama.com"], ["p", "Ryan T. Cordry, D.O., has joined Southlake Orthopaedics Sports Medicine and Spine Center, a division of SOA. Cordry specializes in orthopedic surgery and joint reconstruction, and his expertise is in conditions of the hip, knee and shoulder. Southlake Orthopaedics offers testing, surgery and rehabilitation services like onsite MRIs and physical therapy. The practice has locations at 4517 Southlake Parkway in Hoover and 3686 Grandview Parkway, Suite 430, in Birmingham."], ["p", "205-985-4111, southlakeorthopaedics.com"], ["h", "Anniversaries"], ["p", "The Casual Pint is celebrating seven years of serving craft beer, weekend brunch and other savory dishes at 5541 Grove Boulevard, Suite 111, in Hoover. Located in The Grove, they offer dishes including cheese curds, pretzels and beer cheese, wings, flatbreads, brats, sidewinders, beer mac and cheese, wraps, salads, burgers, sandwiches and more. The Casual Pint is open Monday and Tuesday from 11 a.m. to 10 p.m., Wednesday and Thursday 11 a.m. to 11 p.m., Friday 11 a.m. to midnight, Saturday 10 a.m. to midnight and Sunday 10 a.m. to 10 p.m."], ["p", "205-783-1108, thegrove.thecasualpint.com"], ["p", "Located at 5363 U.S. 280 West, Suite 105-B, in Hoover, Champion Cleaners is celebrating its 20th anniversary at its Greystone store. They offer dry cleaning services that include hand-pressing the clothes, on-site cleaning, executive shirt service with add-ins, complete repair, alteration services and other add-on services. Owners David and Sherry Whitehurst opened the first location on Rocky Ridge Road 24 years ago, and their son, Mark, became the general manager in 2017. Champion Cleaners in Greystone is open Monday through Friday from 7 a.m. to 6 p.m. and Saturday 9 a.m. to noon. They also have locations in Vestavia Hills, Crestline and Calera."], ["p", "205-408-2797, championcleaners.com"], ["p", "Moss Rock Pharmacy is celebrating its fourth anniversary in The Preserve at 610 Preserve Parkway, Suite 160, next to Vecchia. The independently owned community pharmacy offers prescription refills, medication therapy management, home delivery, health screenings, immunizations, travel vaccinations, over-the-counter products and gifts. The pharmacy is open Monday through Friday from 8:30 a.m. to 6:30 p.m. and Saturday 8:30 a.m. to 2 p.m."], ["p", "205-332-3888, mossrockpharmacy.com"], ["p", "Heritage Preschool is celebrating its sixth anniversary in Hoover at 2700 Ross Bridge Parkway. They teach children from infants through kindergarten, focusing on developmental milestones in four specific areas: spiritual, physical, social and academic. Heritage Preschool offers activities including dance, martial arts and sports programs, as well as an outdoor playground and splash pad. They also have locations in Homewood, Pelham, Huntsville, Trussville and Liberty Park. The Ross Bridge location is open Monday through Friday from 7 a.m. to 6 p.m."], ["p", "205-547-2313, heritagepreschool.com/ross-bridge"], ["h", "Closings"], ["p", "Desi Twist, an Indian/Pakistani restaurant and bar, closed Sept. 1 at 1031 Brocks Gap Parkway in Hoover until further notice. The team shared that they appreciate their customers’ support and understanding and will keep them posted. Desi Twist was open Tuesday through Thursday and Sunday from 11 a.m. to 9 p.m. and Friday and Saturday 11 a.m. to 10 p.m."], ["p", "205-593-4034"]], "source": "https://hooversun.com/businesses/hoover-business-happenings-october-2026/", "placement": "", "views": 0}, {"id": "a1004", "slug": "proposed-riverchase-community-center-hits-roadblock", "title": "Proposed Riverchase community center hits roadblock", "dek": "Hoover staff is not recommending a proposed 30,000-square-foot community center in the Riverchase Office Park, and the zoning case was continued for a fuller traffic study.", "section": "news", "subsection": "", "author": "Jon Anderson", "date": "2026-10-01T21:32:00", "image": "img/04.jpg", "caption": "A 30,000-square-foot community center has been proposed for this 7.5-acre tract on Concourse Parkway, off River-chase Parkway East in the Riverchase Office Park.", "credit": "Map courtesy of city of Hoover.", "status": "published", "body": [["p", "A proposal for a new 30,000-square-foot community center in the Riverchase Office Park is running into snags."], ["p", "A group called the Alabama Merchants Association is proposing to put the community center on 7.5 acres at 900 Concourse Parkway, off Riverchase Parkway East, between the ABC 33/40 television station and Homewood Suites by Hilton hotel."], ["p", "However, the city of Hoover staff is not recommending approval of the “conditional use” request because the property is zoned for office use and the city’s comprehensive plan calls for that space to be used for office and light industrial purposes, City Planner Mac Martin said."], ["p", "In the view of city staff, a community center would not be the highest and best use of the property, Martin said."], ["p", "The site is currently owned by Harbert Properties Corp., but the group interested in buying the site is the Alabama Merchants Association. That is a group that represents owners of numerous gasoline stations and convenience stores, but the group also is connected to a religious community, Martin said."], ["p", "The organization has not been completely clear about its intended uses of the property but has indicated it is contemplating multiple uses that include a recreational center, office space and a place of worship, Martin said."], ["p", "The original traffic study submitted by Skipper Consultants based its expected traffic counts on traffic that would be generated for a recreational community center that is similar to a YMCA facility."], ["p", "A map submitted with the conditional use application shows about 350 parking spaces planned for the community center. The center is expected to generate 865 trips on an average weekday, according to the traffic study."], ["p", "But that traffic study did not contemplate traffic that might accompany all the uses being contemplated, Martin said. So the case was continued by the Planning and Zoning Commission both in August and September to allow time for a more comprehensive traffic study to be conducted."], ["p", "However, Martin noted at the September meeting that the Alabama Merchants Association also continues to look at alternative locations for its community center and could bring forward a new conditional use application at a different site. That is to be determined."], ["p", "In the meantime, the application for the site at 900 Concourse Parkway is scheduled to come back to the zoning board on Oct. 5."], ["p", "In other business in September, the zoning board also postponed a decision on final plans for four lots zoned as “planned industrial” in Trace Crossings at the corner of Stadium Trace Parkway and Flemming Parkway due to a disagreement between city staff and the developer over the timing of needed stormwater improvements."], ["p", "Developer Jonathan Belcher of Signature Homes is proposing to make off-site stormwater improvements downstream to fix a flooding problem at that intersection, but city staff members don’t want to approve building permits until that work is completed because of the risk of further flooding problems."], ["p", "Belcher is seeking permission to get building permits before that work is completed, saying he doesn’t want to be working on the fix while school is in session because students walk to and from school in that area. He won’t be able to complete the stormwater fix over fall break, so it likely would be the winter break before the work could be completed, he said. His potential buyers of land are ready to get started on their development, which will be an economic boost for the city, he said."], ["p", "That case also is scheduled to come back to the zoning board on Oct. 5."]], "source": "https://hooversun.com/news/proposed-riverchase-community-center-hits-roadblock/", "placement": "top", "views": 0}, {"id": "a1005", "slug": "editor-s-note-october-2026", "title": "Editor's Note: October 2026", "dek": "Kyle Parmley reflects on October as a fresh start for local families, schools, football and community life.", "section": "opinion", "subsection": "Editor's Perspective", "author": "Kyle Parmley", "date": "2026-10-01T21:25:00", "image": "img/05.jpg", "caption": "", "credit": "", "status": "published", "body": [["p", "Did you know that this newspaper is just one of the six monthly publications we produce at Starnes Media each month?"], ["p", "The Cahaba Sun covers Trussville, Village Living covers Mountain Brook and we also put together the Hoover Sun, Vestavia Voice, Homewood Star and 280 Living papers on a monthly basis."], ["p", "One of my favorite things about overseeing the production of each of these publications is the unique identity each community possesses. Different things are important to different towns and residents are far more interested in certain topics than others."], ["p", "But one thing that is not unique to any of these places is how much the people care about the place they live, the amount of interesting people all around them."], ["p", "Know of an event we need to highlight? How about that man or woman in town that has such a cool story? We’d love to hear from you! Send me an email at kparmley@starnesmedia.com with any thoughts and ideas. Thanks for reading!"]], "source": "https://hooversun.com/opinion/editors-perspective/editor-s-note-october-2026/", "placement": "", "views": 0}, {"id": "a1006", "slug": "hoover-officials-aim-to-fix-interstate-lighting-woes", "title": "Driving in the dark: Hoover officials aim to fix interstate lighting woes", "dek": "Many Interstate 65 and Interstate 459 streetlights in and around Hoover are out, and officials say repairs are complicated because responsibility is shared among cities, ALDOT and utility equipment.", "section": "news", "subsection": "", "author": "Jon Anderson", "date": "2026-10-01T21:18:00", "image": "img/06.jpg", "caption": "An unlit stretch of Interstate 65 between Alford Avenue and U.S. 31.", "credit": "Photo by David Leong.", "status": "published", "body": [["p", "If you’re driving on Interstate 459 or Interstate 65 in or around Hoover at night, there’s a good chance you’ll be driving in the dark."], ["p", "Many of the interstate streetlights are not working. Hoover officials said they try to keep an eye on outages and address them as they are reported, but there appear to be gaps in the process."], ["p", "On I-65 in early September, there were 23 interstate streetlights out on the southbound side between Alford Avenue and U.S. 31, three more out between U.S. 31 and I-459, and 10 out between I-459 and Valleydale Road."], ["p", "On the northbound side of I-65, there were eight streetlights out between Valleydale and I-459, five out between I-459 and U.S. 31, and 21 out between U.S. 31 and Alford Avenue."], ["p", "On I-459, there were 24 lights out between I-65 and Galleria Boulevard. And there are no light poles on I-459 south of Galleria Boulevard, except at the bottom of the exit ramps at John Hawkins Parkway."], ["p", "John Anthony, Hoover’s traffic engineer, and Eddie Pickett, Hoover’s senior traffic signal technician who keeps an eye on streetlights in key corridors, said they try to spot the lights that are out and address problems that are reported and determined to be Hoover’s responsibility."], ["p", "Pickett reports issues to Anthony, and Anthony gets Stone and Sons Electrical to replace bulbs or make other repairs as needed, they said."], ["p", "Pickett said it’s his understanding that Hoover is responsible for lights on I-459 between I-65 and Galleria Boulevard and on I-65 between Valleydale Road and U.S. 31, as well as some at the intersection of I-65 and Alford Avenue. But he didn’t think Hoover was responsible for any between Alford and U.S. 31 on either side of the interstate."], ["p", "Vestavia Hills officials acknowledge that their city is responsible for some of the lights on I-65 between I-459 and Alford but say Hoover is responsible for many as well, particularly on the southbound side between Alford and U.S. 31."], ["p", "Lori Beth Kearley, the public services director for Vestavia Hills, said the city wants to tackle the problem with interstate lighting, but it’s much more complicated than many people realize."], ["p", "“It’s not just a matter of bulbs being out,” Kearley said."], ["p", "Sometimes, poles get knocked down. Other times, it’s a problem with the wiring, a fuse, a ballast or other electrical equipment, or it could be a problem with the power source sending electricity to the light pole. The age of the lighting infrastructure along the interstates is a big factor, Kearley said."], ["p", "But perhaps the biggest challenge is how maintaining the interstate lights is not the responsibility of a single entity, said Jeff Downes, Vestavia Hills’ city manager."], ["p", "Years ago, the Alabama Department of Transportation turned over maintenance of interstate lights to the various jurisdictions where the lights are, Downes said. And that can get complicated quickly with the way municipal boundaries weave around one another and along the interstates."], ["p", "On I-459, between Liberty Park and I-65, the jurisdictions include Vestavia Hills, Mountain Brook, Birmingham, Hoover and unincorporated Jefferson County. On I-65, between I-459 and Alford Avenue, it’s mostly Vestavia Hills or Hoover."], ["p", "Jon Paepcke, ALDOT’s communications coordinator for the east-central region of the state, which includes the Birmingham area, shared a statement from the agency that interstate lighting in the Birmingham metro area is a patchwork system."], ["p", "“Much of it was added decades after the original system was built, often at the request of local governments,” the ALDOT statement said. “In fact, cities accepted long-term maintenance responsibilities when they asked for these improvements — a common, deliberate practice nationwide.”"], ["p", "“Today, while ALDOT is solely responsible for maintaining some of the interstate lighting, primarily in the unincorporated areas, most of the lights were installed inside city limits,” ALDOT said. “We prioritize repairs to state-owned fixtures when we are made aware of issues in those locations. The system overall faces serious challenges: aging infrastructure, vandalism and copper theft.”"], ["p", "One of the big challenges that cities face is figuring out and keeping up with who is responsible for which light poles and how to cooperate to tackle problems that involve multiple jurisdictions, Downes and Kearley said."], ["p", "“Without having information about who is responsible for what poles, as poles got knocked down or various things have happened to the infrastructure, no one’s put them back up. No one has gone out and done these repairs, and over time, it’s just become more and more of an issue because of not knowing who is responsible,” Kearley said. “I think clearing that up is obviously the first step.”"], ["p", "Vestavia Hills city employees have done their own inventory of the light poles along I-459 and I-65 and determined that fewer than 10 are the responsibility of Vestavia Hills, Downes said."], ["p", "But Alabama Power Co., which has much more expertise with light poles, has agreed to do an independent inventory that can serve as a resource for all the jurisdictions to help each of them identify what poles are their responsibility and collaborate to solve problems, Downes said."], ["p", "Sometimes, poles in one jurisdiction are connected to poles in another jurisdiction, and a break in the wiring or a problem with a power source can kill the entire network, Kearley said."], ["p", "“What happens at a Vestavia pole could impact what happens in Hoover or Birmingham or vice versa,” Kearley said. “There is overlap in the municipal limits regarding the service centers that are servicing these light poles. One side of the interstate is Hoover, and the other side is Vestavia. You may have two in a row that are Hoover and then Vestavia and then Hoover again. If those are all coming off the same service, that’s where it gets complex. If somebody hits a pole in Vestavia, it can affect the lights in Hoover, too, or vice versa.”"], ["p", "It’s going to require collaboration sometimes to get the lights working again, Downes said. Figuring out what the problem is, what the solution should be and who all should pay to fix it can be complex, especially when different jurisdictions have varying financial resources and different priorities, Downes said. “That’s what we’re trying to work through.”"], ["p", "Alabama Power in mid-September was still in the process of developing its inventory of the interstate light poles and the problems affecting each one, Kearley said."], ["p", "Anthony and Pickett said they had not heard from Alabama Power yet about the multi-jurisdictional effort but would be happy to work with the power company on that."], ["p", "There has been a little bit of uncertainty about who is responsible for some areas, Anthony said. “As soon as we find out which ones are ours, we’re going to have our contractor get out and replace some of them for us,” he said."], ["p", "Anthony said he was aware some of the high-mast interchange lighting was out and would be working with the city’s contractor to replace those lights. Pickett said he knew there were a lot of lights out on I-65 between I-459 and Valleydale, and he has reported that there is no power going to the contactors in the junction boxes that supply electricity to the string of poles, he said."], ["p", "The problems with interstate lighting extend far beyond the borders of Hoover. There were at least 34 interstate lights out on I-65 between Alford Avenue and downtown Birmingham in early September and 38 more lights out between Interstate 59/20 and Fultondale."], ["p", "And on I-459, between U.S. 280 and Grants Mill Road, there were 108 light poles without working lights. There were some lights working at the intersection of I-459 and U.S. 280, but only two light poles between U.S. 280 and Liberty Parkway had working lights."], ["p", "ALDOT has consistently offered to partner 50-50 with cities to replace outdated systems, with locally controlled federal funds available for local shares, the statement from ALDOT said."], ["p", "“That’s a strong and generous commitment of state resources,” the statement said. “Some surrounding states do not follow this practice.”"], ["p", "Currently, ALDOT is partnering with Birmingham to replace all the lighting along I-59 from 66th Street North to I-459. The agency expects to approve a contract for the work by the end of the year and begin the project early in 2027."], ["p", "“This is a shared responsibility, and ALDOT remains committed to being a proactive partner,” the statement said. “We’re optimistic about the new momentum and ongoing conversations with local governments to improve lighting in the region.”"]], "source": "https://hooversun.com/news/hoover-officials-aim-to-fix-interstate-lighting-woes/", "placement": "lead", "views": 0}, {"id": "a1007", "slug": "hoover-woman-opens-coffee-truck", "title": "Hoover woman opens coffee truck", "dek": "Jessica Maldonado, a mother of six who also works another job, opened Something Simple Coffee + Sips, a mobile coffee, lemonade and energy-drink truck serving Hoover and neighboring cities.", "section": "business", "subsection": "", "author": "Lauren H. Dowdle", "date": "2026-10-01T21:11:00", "image": "img/07.jpg", "caption": "Jessica Maldonado and her family in front of her new coffee truck before the soft opening of Something Simple Coffee at The Preserve.", "credit": "Photo by Savannah Schmidt.", "status": "published", "body": [["p", "There’s nothing simple about starting a new business, especially for someone who is raising six children and works another job. But for Jessica Maldonado, simple is exactly what she was going for when she opened her mobile coffee and drinks truck in June."], ["p", "Her truck, Something Simple Coffee + Sips, offers a variety of coffee, lemonade and energy refresher drinks at locations across Hoover and neighboring cities."], ["p", "A Hoover native, Maldonado said she wanted to start her business here and continue planting roots in the community with her family, including her children: Reilly, 19; Mayah, 17; Madilyn, 8; Isabelle, 6; Sophia, 3; and Noah, 1. Her husband, Ignacio, is a detective with the Hoover Police Department, and Jessica will serve on the PTO board at Gwin Elementary School this year."], ["p", "She has also formed connections through her time working as a server, shift lead and manager at various restaurants. Now an administrative assistant at J. Alexander’s, she said that job has helped her learn more about the business aspect of running a restaurant, which made her wonder what else she could do with that experience."], ["p", "“I just started thinking, ‘Why can’t I do this for myself and build something that is mine?’” Maldonado said. “I would be able to coordinate and accommodate my schedule and make my own hours, and I wouldn’t have to miss out on the kids’ events and school activities.”"], ["p", "That question transformed into an idea to open a coffee shop and later evolved into having a mobile coffee truck."], ["p", "“Coffee was always something that my husband and I enjoyed, and it was something that I could go and do with my friends too,” she said. “It just gives you that sense of comfort, and I wanted to be able to give that back.”"], ["p", "Maldonado found a horse trailer that had been converted into a coffee trailer and began making it her own. After two years of planning and overcoming obstacles to start a new business, that dream to build something of her own came true when she opened Something Simple Coffee + Sips."], ["p", "While coffee was at the center of her business, Maldonado said she also wanted to offer other drink options. That idea came after attending an event with her children where one wanted a dirty soda, and another wanted lemonade. Having multiple children, she said she knew she couldn’t stand in line for multiple vendors — and didn’t want other parents to face that same dilemma."], ["p", "“I wanted everything to be easy and to have something for everyone,” Maldonado said."], ["p", "Her menu includes cold brews like caramel, sweet cream, mocha and brown sugar, which is her personal favorite. There are also lemonades with flavors like strawberry, peach, blue raspberry, mango and watermelon. For those needing a bit more energy, she offers refreshers that combine peach/pineapple, strawberry/blue raspberry, mango/orange, pineapple/coconut and cherry/lime using the plant-based Lotus energy drink."], ["p", "Other favorites are her dirty sodas like orange dream, southern Dr. Pepper, vanilla root beer, berry Sprite and the classic dirty Coke. During the fall, she will also add hot drinks like lattes, macchiatos and hot chocolate. But no matter the drink, she said she’s committed to using high-quality, simple ingredients and providing a personalized experience."], ["p", "That theme of simplicity is also carried over into her sizes and pricing. All of her drinks are 20 ounces and $6, and she said each one is made with one special ingredient: love."], ["p", "“Even though I might not know you, I’m really pouring love into what I’m about to give you,” she said. “You’re going to be welcomed with a warm smile, a great conversation and a drink that’s easy to order.”"], ["p", "Opening her drink truck has been a true family effort, she said, from her mother helping her get set up as an LLC to her husband playing a role in naming the business."], ["p", "“I told him I just wanted the name to be something simple,” Maldonado recalled. “As soon as I said the words, he looked at me and was like, ‘That’s it.’”"], ["p", "Her children have also supported her throughout this process. Her older daughters can sometimes be spotted serving customers from the trailer, and the younger ones are her taste testers. She said she’s also received encouragement and help from friends."], ["p", "“When you have that type of community behind you, it really helps you feel like you have the confidence to do it,” Maldonado said."], ["p", "While she hasn’t walked this journey alone, Maldonado said it was important that she could manage every aspect of the trailer and business on her own. From the trailer’s plumbing to the electrical system, she wanted to know how to handle it all."], ["p", "“I didn’t want to be somewhere and wonder how to fix it. I wanted this to be my journey,” she said. “It’s made me that much more proud of where I came from. I can say I did this for myself.”"], ["p", "That knowledge was put to the test the first time she took the trailer to an event. While driving there, she had to swerve to miss a car after it made a hard stop. The trailer swayed, causing several of her items and supplies to fall over, including her espresso machine. While some might have backed out of the event, Maldonado cleaned up the aftermath and made it there — and none of her customers could tell anything had gone wrong."], ["p", "“In that moment, there was so much that I learned. When you’re opening your own business, you’ll have stuff like that happen,” she said. “There’s a learning opportunity in every single event that you participate in.”"], ["p", "She also hopes her children will learn from her endeavor and see they can think outside of the box."], ["p", "“I want them to know you don’t have to run with whatever society thinks you should be doing,” Maldonado said. “If you want to open a coffee truck, just do it. You don’t need the approval of everyone else. You’re the one who is going to determine your happiness.”"], ["p", "She’s always looking for new locations to bring the trailer, but she can often be spotted at places like The Preserve, hospitals, school activities and local events. Maldonado will also be at Taste of Hoover in October at Aldridge Gardens. People can also book the mobile coffee trailer for special occasions like weddings, birthdays, festivals, farmer’s markets and school events."], ["p", "One day, she said she’d love to open a brick-and-mortar coffee and drinks shop in Hoover. But for now, she’s excited to get to know the community and earn their trust with both her and the products."], ["p", "“My favorite part is when they take a sip and they’re smiling after I handed them a drink I made with love,” she said."], ["p", "She posts her weekly schedule on the Something Simple Coffee + Sips social media pages. To see the full menu or book the trailer for an event, visit somethingsimplecoffee.com."]], "source": "https://hooversun.com/businesses/hoover-woman-opens-coffee-truck/", "placement": "", "views": 0}, {"id": "a1008", "slug": "spain-park-anglers-win-high-school-fishing-tournament-on-lak", "title": "Spain Park anglers win high school fishing tournament on Lake Guntersville", "dek": "Spain Park anglers James Monson and Greyson Price won a Major League Fishing high school tournament on Lake Guntersville, qualifying for the 2027 national championship.", "section": "sports", "subsection": "Spain Park", "author": "Staff", "date": "2026-10-01T11:51:19", "image": "img/08.jpg", "caption": "", "credit": "Photo courtesy of Major League Fishing", "status": "published", "body": [["p", "Spain Park High School's fishing team of James Monson and Greyson Price won the Major League Fishing Abu Garcia High School Fishing Open on Lake Guntersville on Saturday, bringing five bass to the scale weighing 20 pounds, 1 ounce."], ["p", "The win qualifies Monson and Price for the 2027 High School Fishing National Championship. The top 10% of teams at each open event advance to the national championship."], ["p", "The Spain Park pair finished ahead of St. Amant High School of St. Amant, Louisiana, whose team of Barritt Babin and Hunter Lambert weighed in five bass at 19 pounds, 9 ounces. Heard County High School of Franklin, Georgia, took third at 18 pounds, 9 ounces, and Forsythe Central High School of Cumming, Georgia, was fourth at 18 pounds, 7 ounces."], ["p", "Two other Alabama teams also earned spots in the national championship. DAR Patriots Fishing Club of Grant placed fifth with 18 pounds, 5 ounces, and Mortimer Jordan High School of Kimberly finished sixth with 16 pounds, 8 ounces."], ["p", "The tournament was hosted by Marshall County Tourism and Sports. MLF Abu Garcia High School Fishing tournaments are free, two-person team events for students in grades 7-12 and are open to any high school club affiliated with MLF or the TBF Student Angler Federation."], ["p", "Complete results from the event are available at MajorLeagueFishing.com."]], "source": "https://hooversun.com/sports/spain-park/spain-park-anglers-win-high-school-fishing-tournament-on-lak/", "placement": "", "views": 0}, {"id": "a1009", "slug": "hoover-events-guide-october-2026", "title": "Hoover events guide: October 2026", "dek": "See what's happening in Hoover in October.", "section": "news", "subsection": "", "author": "Kristi Sellers", "date": "2026-10-01T11:33:29", "image": "img/09.jpg", "caption": "", "credit": "", "status": "published", "body": [["h", "Shades Crest Arts And Crafts Fair"], ["p", "Where: Shades Crest Baptist Church, Fellowship Hall, 452 Park Ave., Hoover"], ["p", "When: Saturday, Oct. 3, 9 a.m. to 3 p.m."], ["p", "Details: Shop locally made art and handmade goods at the annual Shades Crest Arts and Crafts Fair. The event brings together artists and crafters for a day of shopping, food and activities at Shades Crest Baptist Church. The fair coincides with the nearby Bluff Park Art Show, making the area a destination for art lovers throughout the day. Proceeds from exhibitor table rentals and food sales will benefit Lift Up the Vulnerable, an organization working to protect and empower vulnerable children and women."], ["p", "Contact: 205-822-1360"], ["p", "More Info: shadescrest.org"], ["h", "Bhm26.2 Race Series"], ["p", "Where: The Finley Center at the Hoover Metropolitan Complex"], ["p", "When: Sunday, Oct. 4, 7 a.m. to 2 p.m."], ["p", "Cost: Varies by race; advance registration required."], ["p", "Details: Hit the pavement for a cause at the BHM26.2 Race Series, a full day of running and family fun benefiting Magic Moments. The event includes a marathon, half marathon, 5-person marathon relay, 10K, 5K and kids fun run, with options for runners of a variety of ages and experience levels. More than 2,000 runners participate in the annual event, which has raised more than $1 million to help bring special experiences to Alabama children facing serious medical conditions. Race day also includes a family-friendly after party with food, entertainment and a kids’ zone."], ["p", "More Info: bhm262.com"], ["p", "ALABAMA WOODWORKERS GUILD ANNUAL MEMBERS EXHIBITION"], ["p", "Where: Hoover Public Library, 200 Municipal Drive, Hoover"], ["p", "When: Oct. 11-15, during regular library hours"], ["p", "Cost: Free"], ["p", "Details: Discover the artistry and craftsmanship of local woodworkers during the Alabama Woodworkers Guild Annual Members Exhibition. Handmade creations from guild members ranging from beginners to master craftsmen will be displayed throughout the Friends Gallery, Shakespeare Room and Southern Voices Gallery. The annual exhibition offers visitors a chance to see a variety of woodworking styles, techniques and projects created by talented artisans from across the area."], ["p", "Contact: 205-444-7800"], ["p", "More Info: hooverlibrary.org"], ["h", "Étouffée Soirée With Byrd & Chase"], ["p", "Where: Jubilee Joe’s Cajun Seafood Restaurant, 5190 Medford Drive, Suite 114, Hoover"], ["p", "When: Sunday, Oct. 18, 5 p.m."], ["p", "Details: Spend a Sunday evening enjoying Cajun cuisine and live music during Étouffée Soirée at Jubilee Joe’s. Byrd & Chase will perform an acoustic mix of country, pop, blues and rock on the patio, with song requests welcome. Grab a plate of your favorite Cajun fare, settle in and enjoy an easygoing evening of food and live local music."], ["p", "Contact: 205-982-7797"], ["p", "More Info: jubileejoes.com"]], "source": "https://hooversun.com/news/hoover-events-guide-october-2026/", "placement": "", "views": 0}, {"id": "a1010", "slug": "volleyball-update-093026", "title": "Jags, Bucs getting into area play", "dek": "Here's a weekly update on Hoover and Spain Park's volleyball teams.", "section": "sports", "subsection": "", "author": "Kyle Parmley", "date": "2026-10-01T09:14:32", "image": "img/10.jpg", "caption": "Spain Park's Sarah Latham (35) serves during action at the Juanita Boddie Tournament at the Finley Center in Hoover, AL on Fri., Aug. 21, 2026. Photo by David Leong.", "credit": "Photo by David Leong", "status": "published", "body": [["p", "Spain Park and Hoover are deep into the middle of their high school volleyball seasons."], ["p", "Spain Park went 2-1 over the past week, with Camdyn Kyes surpassing 1,500 career digs along the way. That stretch pushed Spain Park to 20-4 on the season."], ["p", "Kyes anchored the back row with 64 digs, 39 receptions on just two errors and five aces. Peyton Harrington added 18 kills, 35 digs and three aces, and Chloe Shumate contributed 37 kills. Sarah Latham chipped in 18 kills and five blocks, and setter Lynlee Franks ran the offense with 67 assists and 20 digs."], ["p", "Spain Park plays in the Margaret Blalock Tournament this weekend, then faces Auburn and Hewitt-Trussville on Oct. 6."], ["p", "Elsewhere, Hoover dropped both of its matches over the past week, falling to Mountain Brook 3-1 on Sept. 24 and Vestavia Hills 3-1 on Sept. 29."], ["p", "Hoover hosts McGill-Toolen on Thursday, then plays in the Margaret Blalock Tournament at Homewood over the weekend, before traveling to Tuscaloosa County on Tuesday."]], "source": "https://hooversun.com/sports/volleyball-update-093026/", "placement": "", "views": 0}, {"id": "a1011", "slug": "aswa-poll-093026", "title": "Bucs, Jags still ranked in ASWA poll", "dek": "This week's Alabama Sports Writers Association rankings are out.", "section": "sports", "subsection": "", "author": "Kyle Parmley", "date": "2026-10-01T02:41:20", "image": "img/11.jpg", "caption": "Hoover safety DJ Waluyn (1)  makes a tackle during a game between Hoover High School and Knoxville Catholic High School on Friday, September 25, 2026, at the Hoover Met. Photo by Barry Stephenson", "credit": "", "status": "published", "body": [["p", "The Alabama Sports Writers Association released its latest high school football poll Wednesday morning."], ["p", "Hoover dropped to No. 9 in Class 6A, down from No. 7 a week ago, after a 20-17 loss to Knoxville Catholic (Tenn.) on a touchdown as time expired. The Bucs, now 3-3, host Thompson this week."], ["p", "Spain Park held at No. 10 after an open date, and the Jaguars travel to Prattville this week."], ["p", "The full Class 6A poll:"], ["h", "Class 6A"], ["p", "Team (first-place); W-L; Pts"], ["p", "1. Thompson (20); 5-0; 240"], ["p", "2. Central-Phenix City; 4-1; 173"], ["p", "3. Prattville; 5-0; 167"], ["p", "4. Vestavia Hills; 4-1; 140"], ["p", "5. Hewitt-Trussville; 3-2; 97"], ["p", "6. Daphne; 4-1; 90"], ["p", "7. Auburn; 3-2; 74"], ["p", "8. Opelika; 2-2; 43"], ["p", "9. Hoover; 3-3; 38"], ["p", "10. Spain Park; 3-2; 37"], ["p", "Others receiving votes: James Clemens (4-1) 21, Fairhope (4-1) 14, Sparkman (5-1) 3, Enterprise (4-2) 2, Carver-Montgomery (3-3) 1."]], "source": "https://hooversun.com/sports/aswa-poll-093026/", "placement": "", "views": 0}, {"id": "a1012", "slug": "shades-crest-arts-and-crafts-fair-returns-for-day-of-local-s", "title": "Shades Crest Arts and Crafts Fair returns for day of local shopping", "dek": "The annual Shades Crest Arts and Crafts Fair will feature handmade goods, food and activities while raising money for an organization serving vulnerable children and women.", "section": "news", "subsection": "", "author": "Staff", "date": "2026-09-30T11:58:47", "image": "img/12.jpg", "caption": "", "credit": "Image courtesy of Shades Crest Baptist Church", "status": "published", "body": [["p", "The Shades Crest Arts and Crafts Fair will return Saturday, Oct. 3, from 9 a.m.-3 p.m. at Shades Crest Baptist Church in Hoover."], ["p", "The annual event brings artists and crafters together in the church's Fellowship Hall, giving visitors an opportunity to shop for locally made art and handmade goods. Food and activities will also be available during the fair."], ["p", "The event coincides with the nearby Bluff Park Art Show, giving art lovers another shopping stop in the area during the day."], ["p", "Proceeds from exhibitor table rentals and food sales will benefit Lift Up the Vulnerable, an organization that works to protect and empower vulnerable children and women."], ["p", "Shades Crest Baptist Church is located at 452 Park Ave. For more information, visit shadescrest.org or call 205-822-1360."]], "source": "https://hooversun.com/news/shades-crest-arts-and-crafts-fair-returns-for-day-of-local-s/", "placement": "", "views": 0}, {"id": "a1013", "slug": "week-7-football-preview-093026", "title": "Week 7 Football Preview: Bucs, Jags with big region games", "dek": "Hoover and Spain Park football is back in action Friday night.", "section": "sports", "subsection": "", "author": "Kyle Parmley", "date": "2026-09-30T10:29:00", "image": "img/13.jpg", "caption": "Hoover running back Jordan Williams (2) runs the ball during a game between Hoover High School and Knoxville Catholic High School on Friday, September 25, 2026, at the Hoover Met. Photo by Barry Stephenson", "credit": "", "status": "published", "body": [["p", "Week 6 is in the books, and the Under the Lights teams are back at it for Week 7. Region play returns this week after many teams took an open date, and others played a non-region matchup."], ["p", "Here’s a quick look at the Week 7 slate. Be sure to follow Under the Lights on X and Facebook for updates all season long. Get all of our coverage in your inbox each Saturday morning as well."], ["p", "Thank you to Southlake Orthopaedics for sponsoring our coverage of Hoover football this season."], ["h", "Hoover (3-3) vs. Thompson (5-0)"], ["li", "Date: Friday, Oct. 2"], ["li", "Time: 7 p.m."], ["li", "Location: Hoover Met"], ["p", "Last week: Hoover fell to Knoxville Catholic 20-17; Thompson had an open date."], ["p", "What to watch: Hoover let a fourth-quarter lead slip away on the final play against Knoxville Catholic, as a last-second Hail Mary gave the Bucs a tough loss to stomach. Hoover will look to rebound against one of its archrivals this week. Thompson, off an open date after a 62-7 win over Tuscaloosa County, has looked nearly unstoppable for much of the season so far, but Hoover has a penchant for playing its best against the Warriors."], ["p", "Last meeting: Hoover beat Thompson 33-30 in 2025. Hoover leads the all-time series with Thompson 26-9."], ["p", "Next week: Hoover travels to Vestavia Hills, while Thompson travels to Hewitt-Trussville."], ["h", "Spain Park (3-2) at Prattville (5-0)"], ["li", "Date: Friday, Oct. 2"], ["li", "Time: 7 p.m."], ["li", "Location: Stanley-Jensen Stadium, Prattville"], ["p", "Last week: Spain Park and Prattville each had an open date."], ["p", "What to watch: Spain Park had an open date to recover from a disappointing loss to Vestavia Hills two weeks ago. When the Jags have played at their top level, they have proven to be the type of team capable of competing with the top teams in the region, of which Prattville has proven to be. Prattville, off a bye after its blowout win over Hewitt-Trussville, is one of two unbeaten teams remaining in Class 6A, Region 3, along with Thompson."], ["p", "Last meeting: Spain Park beat Prattville 19-16 in 2013. Spain Park leads the series 2-1."], ["p", "Next week: Spain Park hosts Tuscaloosa County, while Prattville hosts Oak Mountain."], ["h", "Briarwood (6-0) at St. John Paul II (0-5)"], ["li", "Date: Thursday, Oct. 1"], ["li", "Time: 7 p.m."], ["li", "Location: Joe Davis Stadium, Huntsville"], ["p", "Last week: Briarwood beat Montgomery Catholic 24-21; St. John Paul II fell to American Christian Academy 50-0."], ["p", "What to watch: Briarwood needed a fourth-down conversion from John Campbell in the final minutes to hold off Montgomery Catholic in its closest game of the season last week. Jamison Barnes and Charlie Allen connecting on a tying touchdown before halftime and the go-ahead score in the third quarter. St. John Paul II enters at 0-5, so the Lions return to region play as heavy favorites."], ["p", "Last meeting: Briarwood and St. John Paul II have never met."], ["p", "Next week: Briarwood hosts John Carroll, while St. John Paul II plays at Randolph."], ["h", "John Carroll (3-2) at Westminster (0-5)"], ["li", "Date: Thursday, Oct. 1"], ["li", "Time: 7 p.m."], ["li", "Location: Earl Van Dyke Stadium, Huntsville"], ["p", "Last week: John Carroll had an open date; Westminster fell to Randolph 51-0."], ["p", "What to watch: John Carroll enters off an open date following back-to-back region wins, the most recent a 30-17 decision over Lee-Scott. Westminster is still winless and the Cavs are expected to win on Thursday evening in Huntsville."], ["p", "Last meeting: John Carroll and Westminster have never met."], ["p", "Next week: John Carroll travels to Briarwood, while Westminster travels to Lee-Scott."], ["h", "Chelsea (0-5) vs. Helena (3-2)"], ["li", "Date: Friday, Oct. 2"], ["li", "Time: 7 p.m."], ["li", "Location: Chelsea High School"], ["p", "Last week: Chelsea had an open date; Helena beat Pleasant Grove 33-27 in overtime."], ["p", "What to watch: Chelsea is still searching for its first win after a tough first half of the season. The Hornets have seen some positive, like a strong finish to the Pelham game two weeks ago, and are hopeful they can begin to see some fruits of their labor over the back half of the year. Helena snapped a two-game slump behind its highest point total of the season, ending Pleasant Grove's four-game winning streak in the process."], ["p", "Last meeting: Helena knocked off Chelsea 21-9 in 2025. Helena leads the all-time series with Chelsea 7-5."], ["p", "Next week: Chelsea travels to Homewood, while Helena hosts Chilton County."], ["h", "Hewitt-Trussville (3-2) at Oak Mountain (1-4)"], ["li", "Date: Friday, Oct. 2"], ["li", "Time: 7 p.m."], ["li", "Location: Heardmont Park"], ["p", "Last week: Hewitt-Trussville and Oak Mountain each had an open date."], ["p", "What to watch: Hewitt-Trussville is looking to bounce back and reestablish its confidence as one of the top teams in Class 6A, Region 3, after a disappointing loss to Prattville two weeks ago. The Huskies enter the second half of the season with a daunting three-week schedule ahead of them following this week. Oak Mountain, off an open date as well, has dropped three straight and is still searching for its first region win."], ["p", "Last meeting: Hewitt-Trussville beat Oak Mountain 36-21 in 2025. Hewitt-Trussville leads the series 11-3."], ["p", "Next week: Hewitt-Trussville hosts Thompson, while Oak Mountain travels to Prattville."], ["h", "Mountain Brook (4-2) vs. Ramsay (5-1)"], ["li", "Date: Friday, Oct. 2"], ["li", "Time: 7 p.m."], ["li", "Location: Spartan Stadium"], ["p", "Last week: Mountain Brook beat Oxford 10-3; Ramsay beat Pinson Valley 34-26."], ["p", "What to watch: Mountain Brook leaned on defense and field position to grind out a low-scoring, complementary-football win over Oxford in non-region play last week. Ramsay has won four straight and enters as one of the hotter teams on the schedule. This game will be a pivotal one in terms of eventually deciding the region titles, as these two teams and Homewood appear to be the frontrunners in Class 5A, Region 4."], ["p", "Last meeting: Mountain Brook beat Ramsay 19-13 in 2016, but Ramsay has won two of the three previous meetings."], ["p", "Next week: Mountain Brook travels to Calera, while Ramsay hosts Pelham."], ["h", "Game of the Week"], ["h", "Homewood (4-1) vs. Calera (4-1)"], ["li", "Date: Friday, Oct. 2"], ["li", "Time: 7 p.m."], ["li", "Location: Waldrop Stadium"], ["p", "Last week: Homewood had an open date; Calera beat Gardendale 42-32."], ["p", "What to watch: Homewood is coming off an open date and has an opportunity to cement its status as one of the Class 5A, Region 4 frontrunners this week. Calera has positioned itself well in the hunt for a playoff spot and will be hungry to knock off the Patriots."], ["p", "Last meeting: Homewood beat Calera 43-21 in 2023. Homewood leads the series 2-0."], ["p", "Next week: Homewood hosts Chelsea, while Calera hosts Mountain Brook."], ["h", "Vestavia Hills (4-1) at Tuscaloosa County (0-5)"], ["li", "Date: Friday, Oct. 2"], ["li", "Time: 7 p.m."], ["li", "Location: Tuscaloosa County High School"], ["p", "Last week: Vestavia Hills and Tuscaloosa County each had an open date."], ["p", "What to watch: Vestavia Hills is off an open date following a three-possession win over Spain Park two weeks ago. Tuscaloosa County has lost 14 of its last 15 games dating back to last season and is entering its first game with an interim coach as well. The Rebels should be able to take care of business and look forward to a big matchup with rival Hoover next week."], ["p", "Last meeting: Vestavia Hills beat Tuscaloosa County 56-10 in 2025. Vestavia Hills leads the series 16-6."], ["p", "Next week: Vestavia Hills hosts Hoover, while Tuscaloosa County travels to Spain Park."], ["h", "Clay-Chalkville (4-1) vs. Pell City (2-4)"], ["li", "Date: Friday, Oct. 2"], ["li", "Time: 7 p.m."], ["li", "Location: Cougar Stadium"], ["p", "Last week: Clay-Chalkville had an open date; Pell City fell to Saraland 68-10."], ["p", "What to watch: Clay-Chalkville is off an open date after christening its new stadium with a 49-14 win over Oxford, and has now won 19 of its last 20 games. Pell City’s record is perhaps a little misleading, as the Panthers have played one of the toughest schedules in the state thus far."], ["p", "Last meeting: Clay-Chalkville beat Pell City 52-9 in 2025. Clay-Chalkville leads the series 16-2."], ["p", "Next week: Clay-Chalkville hosts Pinson Valley, while Pell City hosts Southside Gadsden."], ["p", "Historical data courtesy of AHSFHS.org."]], "source": "https://hooversun.com/sports/week-7-football-preview-093026/", "placement": "", "views": 0}, {"id": "a1014", "slug": "hoover-council-approves-206-million-in-government-spending-f", "title": "Hoover council approves $206 million in government spending for 2027", "dek": "The budget includes $10.4 million in capital projects for 2027.", "section": "news", "subsection": "", "author": "Jon Anderson", "date": "2026-09-29T09:36:00", "image": "img/14.jpg", "caption": "The Hoover City Council discusses the city's 2027 budget on Monday, Sept. 28, 2026.", "credit": "Photo by Jon Anderson", "status": "published", "body": [["p", "The Hoover City Council on Monday night approved a 2027 budget that includes $178 million in spending from the city’s general fund and a total of $206 million in spending from all government funds."], ["p", "The $178 million general fund budget represents a 4% increase from the original 2026 general fund budget. The council also approved $10.4 million for capital projects and $17.7 million in spending from special revenue accounts that include gas tax money and Municipal Court programs."], ["p", "Hoover Mayor Nick Derzis said in a statement that this budget holds essential services steady while confronting slower revenue growth, rising operating costs and a backlog of infrastructure and equipment needs."], ["p", "The budget also will add $500,000 to the city’s general fund, growing it to more than $74 million by Sept. 30, 2027, which represents roughly five months of operating costs."], ["h", "Essential Services"], ["p", "“This is a responsible budget grounded in reality,” Derzis said. “Our revenues are essentially flat, while many of our costs continue to increase. We have significant capital needs that have accrued over many years, and we cannot address all of them in one or two budget cycles. We will be disciplined about what we spend and relentless about finding ways to operate more efficiently.”"], ["p", "Derzis said earlier this year, he directed his staff to find ways to cut costs by operating more efficiently, and those efforts will save the city $1.5 million annually. The administration also retired some long-term debt, reducing interest costs and dropping annual debt service by approximately $2.6 million. That provides the flexibility needed to balance the 2027 budget while maintaining progress on key priorities, city officials said."], ["p", "Restructuring administration of the city’s health plan and discontinuing the employee health clinic, where costs were rising 50% or more, are expected to save approximately $1.2 million annually."], ["p", "“These were necessary decisions,” Derzis said. “These efficiencies let us keep funding essential services without simply adding expense. But we cannot cut our way to long-term prosperity while providing the police, fire, roads, parks and other services our citizens expect.”"], ["p", "Derzis said he was glad the city can provide a 2% cost-of-living adjustment for city employees in fiscal 2027 and not pass along increases in health care costs to employees."], ["p", "Department heads requested 31 new city employee positions be added in 2027 at a cost of $2.76 million, plus $635,0000 worth of position upgrades and increased overtime, Chief Financial Officer Melinda Lopez said."], ["p", "However, Derzis did not include any new positions or personnel upgrades in his budget request until the city has time to conduct a new study to analyze the city’s staffing and compensation levels to see how Hoover compares with other municipalities and to make sure compensation is fair between different city departments, Lopez said. The goal is to complete that study sometime in fiscal 2027, and the timing of any recommended changes would depend on when that study is completed, she said."], ["h", "Capital Needs"], ["p", "Shortly after taking office, the Derzis administration conducted a citywide review that identified more than $150 million in capital needs over the next three to five years, spanning public safety equipment, vehicles, facilities, roads, drainage, youth sports and parks."], ["p", "The administration began addressing that backlog with a $15 million capital project plan for 2026, and the council approved another $10.4 million in capital projects for 2027. “We are making progress, but nobody should mistake progress for having solved the problem,” Derzis said. “Hoover is still catching up from years in which capital replacement and preventive maintenance did not receive the attention they required. We must prioritize the most critical needs and work through that backlog over several years.”"], ["p", "The 2027 budget includes $3.75 million for a partial roof replacement for the Hoover Public Safety Center, $3 million for street resurfacing, about $1 million for police body-worn cameras and drone equipment, about $1.8 million for more stormwater drainage improvements, $1.6 million for replacement police vehicles, $1.65 million for a replacement fire engine and medical transport unit, an extra $1 million for the Valleydale Road widening project, about $1 million for breathing equipment for the Fire Department and an additional $500,000 for building a new Hoover Lake House on Municipal Lane and $500,000 for improvements at various city parks and sports facilities."], ["p", "“These are not luxury items,” Derzis said. “Fire engines have to be replaced, roofs repaired, roads resurfaced and drainage problems corrected. Deferring those needs does not make them disappear, and waiting usually makes them more expensive.”"], ["p", "Hoover’s residential garbage contract is projected to increase by about $1.8 million over the original 2026 budget, driven by a 4.6% contractual Consumer Price Index increase and a higher fuel surcharge. The total cost of that service now exceeds the city’s annual residential property-tax collections available for city operations."], ["p", "“Cities face the same pressures as families and businesses,” Derzis said. “Insurance costs more. Equipment costs more. Construction costs more. Contracted services cost more. But we cannot stop providing police protection, fire and EMS coverage, garbage collection or road maintenance.”"], ["h", "Planning"], ["p", "The 2027 budget includes $150,000 to update the city’s comprehensive plan and $100,000 for a space study of city facilities intended to explore opportunities for future facility reapportionment and consolidation."], ["p", "“Hoover has too often reacted to problems after they occurred, and that costs more,” Derzis said. “We have seen it in emergency sewer repairs and at facilities such as the Hoover East Sports Park. We will not ignore these problems, and we will address these needs proactively.”"], ["h", "Protecting And Growing Revenue"], ["p", "Derzis said the city also continues to lose about $10 million annually because of the way Alabama’s simplified sellers use tax – or sales tax for online purchases – is structured."], ["p", "“The continued impact of SSUT on Hoover is not sustainable,” the mayor said. “We will keep controlling expenses here at home, but we also must address a system that diverts revenue away from the communities where people live and receive municipal services. Relief will be one of our highest legislative priorities in 2027.”"], ["p", "The 2027 budget is balanced, but that doesn’t mean every challenge has been solved, Derzis said."], ["p", "“The rate of revenue growth has slowed over several years, and costs continue to rise. SSUT continues to impact our revenue base, and major developments such as Riverwalk Village and the Riverchase Galleria have not yet reached their potential as revenue drivers for our city.”"], ["p", "The city’s responsibility is to acknowledge these realities and act on them by continuing to control recurring expenses, taking care of the assets taxpayers already own and pursuing economic growth, Derzis said."], ["p", "“That is how we protect taxpayers and preserve the level of service Hoover residents expect. We are not going to fix years of deferred needs overnight,” Derzis said. “But we are going to identify them, prioritize them and work through them responsibly. Hoover has tremendous strengths, and protecting them takes planning and sometimes difficult decisions.”"], ["h", "Chamber Support"], ["p", "Counciwoman Khristi Driver said some people may have noticed the city’s annual contribution to the Hoover Area Chamber of Commerce has dropped from $159,000 to $109,000, including the $59,000 the city pays to cover the chamber’s rent in The Offices at 3000 Riverchase office tower next to the Riverchase Galleria."], ["p", "This change is not intended to pull the rug out from beneath the chamber, but it does return the city’s financial contribution to the chamber back to what it was before the chamber began its Elevate Hoover campaign a few years ago and brings Hoover more in line with neighboring communities, Driver said."], ["p", "The chamber is still important to the city, and the city government wants to support the chamber, she said."], ["p", "“We feel that this is a healthy amount of support that the mayor has suggested with this budget,” she said."]], "source": "https://hooversun.com/news/hoover-council-approves-206-million-in-government-spending-f/", "placement": "top", "views": 0}, {"id": "a1015", "slug": "recent-real-estate-sales-in-hoover-september-2026", "title": "Recent real estate sales in Hoover: September 2026", "dek": "See some recent real estate sales in Hoover.", "section": "business", "subsection": "", "author": "Staff", "date": "2026-09-28T21:16:00", "image": "img/15.jpg", "caption": "", "credit": "", "status": "published", "body": [["p", "ADDRESS: 4575 Lynton Drive"], ["h", "• Bed/Bath: 4/4.5"], ["p", "• SQUARE FOOTAGE: 3,830 sq. ft."], ["p", "• NEIGHBORHOOD: Sage Park"], ["h", "• List Price: $846,000"], ["h", "• Sale Price: $836,920"], ["p", "ADDRESS: 1036 Clifton Road"], ["h", "• Bed/Bath: 5/4"], ["p", "• SQUARE FOOTAGE: 3,425 sq. ft."], ["p", "• NEIGHBORHOOD: Bradbury at Blackridge"], ["h", "• List Price: $707,000"], ["h", "• Sale Price: $680,000"], ["p", "ADDRESS: 1062 Danberry Lane"], ["h", "• Bed/Bath: 3/2.5"], ["p", "• SQUARE FOOTAGE: 3,483 sq. ft."], ["p", "• NEIGHBORHOOD: Danberry"], ["h", "• List Price: $749,900"], ["h", "• Sale Price: $660,000"], ["p", "ADDRESS: 1208 Braemer Court"], ["h", "• Bed/Bath: 5/3"], ["p", "• SQUARE FOOTAGE: 3,188 sq. ft."], ["p", "• NEIGHBORHOOD: Greystone"], ["h", "• List Price: $640,000"], ["h", "• Sale Price: $627,500"], ["p", "ADDRESS: 2245 McGwier Drive"], ["h", "• Bed/Bath: 3/2"], ["p", "• SQUARE FOOTAGE: 2,306 sq. ft."], ["p", "• NEIGHBORHOOD: Bluff Park"], ["h", "• List Price: $385,000"], ["h", "• Sale Price: $385,000"], ["p", "ADDRESS: 4608 Guilford Cove"], ["h", "• Bed/Bath: 2/2"], ["p", "• SQUARE FOOTAGE: 1,581 sq. ft."], ["p", "• NEIGHBORHOOD: Greystone Farms"], ["h", "• List Price: $345,000"], ["h", "• Sale Price: $345,000"]], "source": "https://hooversun.com/businesses/recent-real-estate-sales-in-hoover-september-2026/", "placement": "", "views": 0}, {"id": "a1016", "slug": "63rd-bluff-park-art-show-to-be-held-oct-3", "title": "UPDATE: 63rd Bluff Park Art Show canceled due to weather concerns", "dek": "The Bluff Park Art Show was scheduled for Saturday.", "section": "news", "subsection": "", "author": "Emily Reed", "date": "2026-09-28T20:08:00", "image": "img/16.jpg", "caption": "Kristin Canan of Hoover checks out photography by Steve Dunlap at the 2025 Bluff Park Art Show.", "credit": "Photo by Jon Anderson.", "status": "published", "body": [["p", "Update Sept. 30: Due to the threat of inclement weather over the weekend, the 63rd Annual Bluff Park Art Show has been canceled."], ["p", "\"We're devastated to have to make this decision, but the safety of our artists, patrons, vendors, and volunteers is of the utmost importance,\" Heather Jones Skaggs said on behalf of the event. \"Thank you to the community for all of your support, and we'll see you next year.\""], ["p", "For more information and updates, visit Bluffparkartassociation.org."], ["p", "In other art news, the Shades Crest Arts and Crafts fair is still on for Saturday, rain or shine, at Shades Crest Baptist Church. Information on the event can be found at this link."], ["p", "The 63rd annual Bluff Park Art Show will take place Oct. 3 beginning at 9 a.m. at Bluff Park Community Park."], ["p", "The event invites patrons to “see, taste, hear, smell and touch” items on display from artists from all over the South."], ["p", "Attendees can come and go throughout the day to peruse works by various artists. Many of the featured artists will be on-site to greet guests face-to-face."], ["p", "“Let your senses be ignited and support your local community of makers, designers, doers and dreamers,” the event promotes."], ["p", "Bluff Park Art Association President Rachael Jamison said this particular event is unique compared to others because all of the artists are chosen through a blind jury process."], ["p", "“Applicants submit photos of their work, and our jury scores them all without knowing who the artists are,” Jamison said. “This ensures a consistently high standard of quality art at the show.”"], ["p", "The BPAA announced Minkyu Lee as the judge for the art show. Lee is a multimedia artist whose practice centers on vessel and furniture making, working primarily with ceramics and wood."], ["p", "Jamison said attendees often enjoy the wide variety of media including paintings, ceramics, fiber arts, sculpture, photography, jewelry, woodworking, glass and more."], ["p", "There will be more than 120 artists in this year’s show."], ["p", "“This event allows everyone the ability to find something that they like,” Jamison said."], ["p", "Roughly 7,000 patrons are anticipated to attend this year’s event."], ["p", "“We will have our always popular kids’ art area run by the Girl Scouts, where parents can sign in their children for art activities while they go look around the show,” Jamison said. “We also have plenty of food trucks this year.”"], ["p", "The food trucks currently slated to attend include G.R.’s Smokehouse, Travelin’ Tom’s Coffee, Kona Ice, Nettie B’s Grill, Domi Empanadas, Sweet Claire’s Caboose, Alabama Peanut, Cookie Fix, South Fizz Soda and The Park Nutrition."], ["p", "Dogs are welcome at the event."], ["p", "Hoover Board of Education school buses will be on a continuous loop to and from Shades Mountain Plaza, Bluff Park United Methodist Church and Shades Mountain Community Church. They are ADA compliant."], ["p", "The city of Hoover shuttles will also be on a continuous loop to and from Shades Crest Baptist Church."], ["p", "Parking is available at Shades Mountain Plaza, 2400 Mountain Drive, Hoover; Bluff Park United Methodist Church, 733 Valley St., Hoover; Shades Crest Baptist Church, 452 Park Ave., Hoover; and Shades Mountain Community Church, 2281 Old Tyler Road, Hoover."], ["p", "The event wraps up at 5 p.m. For more information, visit bluffparkartassociation.org."]], "source": "https://hooversun.com/news/63rd-bluff-park-art-show-to-be-held-oct-3/", "placement": "", "views": 0}, {"id": "a1017", "slug": "city-rivalry-highlights-october-schedule-for-bucs-jags", "title": "City rivalry highlights October schedule for Bucs, Jags", "dek": "Hoover and Spain Park football face region opponents in October, including the Oct. 16 city rivalry, as playoff seeding takes shape in an amended six-of-eight format.", "section": "sports", "subsection": "", "author": "Kyle Parmley", "date": "2026-09-28T20:01:00", "image": "img/17.jpg", "caption": "Hoover kicker Steele Witschy (39) watches a kick during a game between Hoover High School and Muscle Shoals High School on Aug. 21 at the Hoover Met.", "credit": "Photos by Barry Stephenson.", "status": "published", "body": [["p", "Hoover High School’s football team opened Class 6A, Region 3 play in September against Hewitt-Trussville, Prattville and Oak Mountain, while Spain Park opened region play against Oak Mountain, Thompson and Vestavia Hills. Both teams now turn to the second half of the region schedule in October."], ["h", "Oct. 2"], ["p", "Hoover hosts Thompson, a series the Bucs lead 26-9, including a 33-30 win last season. Four of the last six meetings between the two have been decided by single digits and the series has often produced one of the region’s most compelling games. Spain Park travels to Prattville, a series it leads 2-1, but the teams have not met since 2013."], ["h", "Oct. 8-9"], ["p", "Spain Park hosts Tuscaloosa County on Oct. 8, a series it leads 9-3, including a 35-14 win in 2023, the last time the teams played. Hoover travels to Vestavia Hills on that Friday. Hoover holds a 39-22 edge in that all-time series, but Vestavia Hills won last year’s meeting 39-30."], ["h", "Oct. 16"], ["p", "Hoover hosts Spain Park in the city rivalry, a series the Bucs lead 21-4, including a 21-10 win last season. All three of the Jags’ on-field wins in the series have come since 2015. Spain Park won 39-27 in 2024 in a thriller, but Hoover avenged that loss with a 21-10 victory last fall."], ["h", "Oct. 23"], ["p", "Hoover travels to Tuscaloosa County, a series the Bucs lead 22-3, including a 51-7 win last season. Hoover has won 15 straight meetings in the series dating to 2012. Spain Park travels to Hewitt-Trussville, a series the Huskies lead 6-3. The teams have not met since 2023, when Spain Park won 50-29."], ["h", "Oct. 29-30"], ["p", "Spain Park closes the regular season at home against James Clemens in a non-region game, a series it leads 3-1, including a 28-7 win last season. The two programs have also met twice in the playoffs, with Spain Park winning a 2015 second-round game and James Clemens winning a 2016 first-round game. Hoover closes the regular season with an open date on Oct. 30."], ["h", "Looking Ahead"], ["p", "Hoover finished 6-5 last season and reached the first round of the Class 7A playoffs under head coach Chip English."], ["p", "Spain Park finished 9-3 and reached the second round of the Class 6A playoffs under fifth-year head coach Tim Vakakes. Both teams’ October schedules will shape their playoff seeding as Class 6A, Region 3 sorts itself out under an amended format that sends the top six of eight teams to the postseason."]], "source": "https://hooversun.com/sports/city-rivalry-highlights-october-schedule-for-bucs-jags/", "placement": "", "views": 0}, {"id": "a1018", "slug": "hoover-city-council-to-consider-2027-budget-on-monday-sept-2", "title": "Hoover City Council to consider 2027 budget on Monday, Sept. 28", "dek": "Mayor Nick Derzis proposed a $178 million general fund budget and total government fund spending of $206 million.", "section": "news", "subsection": "", "author": "Jon Anderson", "date": "2026-09-26T23:39:00", "image": "img/18.jpg", "caption": "Hoover City Council members, from left, are Robin Schultz, Gene Smith, Ashley Lovell, Khristi Driver, Derrick Murphy, Casey Middlebrooks and Steve McClinton.", "credit": "Photo from Hoover City Council Facebook page", "status": "published", "body": [["p", "The Hoover City Council on Monday plans to consider the city’s budget for fiscal 2027, which begins Oct. 1."], ["p", "Chief Financial Officer Melinda Lopez two weeks earlier presented Mayor Nick Derzis’ budget proposal, which included proposed spending of $178 million from the general fund, up 4% from the original 2026 general fund budget."], ["p", "Derzis proposed total government fund spending of $206 million for 2027, including $10.4 million in capital projects and $17.7 million in spending from special revenue accounts that include gas tax money and Municipal Court programs."], ["p", "His budget includes a 2% cost-of-living increase for city employees (which would be in addition to any step increases employees get for longevity), Lopez said."], ["p", "Some of that cost increase would be offset by eliminating the city’s funding of a health clinic for employees, where costs were increasing 50% or more, she said. The city also expects to save about $420,000 annually by changing its fee structure for insurance with Blue Cross and Blue Shield of Alabama, she said."], ["p", "Derzis’ budget proposal also includes a $1.8 million increase for garbage service, $3.75 million for a partial roof replacement for the Hoover Public Safety Center, $3 million for paving projects, about $1 million for police body-worn cameras and drone equipment, about $1 million for more stormwater drainage improvements in the Green Valley community, an extra $1 million for the Valleydale Road widening project and about $1 million for breathing equipment for the Fire Department."], ["p", "See more details about Derzis’ proposed budget here."], ["p", "In other business Monday, the City Council is scheduled to consider:"], ["li", "Appointing Sam Eisa, former Hoover fire Chief Chuck Wingate and Kim Starling to the city’s Medical Clinic Board"], ["li", "Amending the 2026 budget to increase spending for garbage pickup by $725,000 due to increased fuel costs and reallocate $417,000 left over from the Riverchase Village draining project to three other drainage projects on Lester Lane, Chester Street and Glenwood Road"], ["li", "Approving an ordinance to allow the sale and use of novelty fireworks and sparklers in the city limits of Hoover under certain conditions. Novelty items include party poppers, snappers, toy smoke devices, snakes, glow worms, wire sparklers and dipped sticks. Fireworks that will still be illegal to sell or use in Hoover include bottle rockers, firecrackers, reloadable shell devices or roman candles, aerial devices, audible ground devices and anything that will detonate or explode."], ["li", "Rescinding an ordinance that penalizes people for false burglar alarms because the previous ordinance adopted in 2002 no longer reflects current alarm system technology"], ["p", "See the full City Council agenda for Monday and supporting documents here. The meeting starts at 6 p.m. at Hoover City Hall at 100 Municipal Lane."]], "source": "https://hooversun.com/news/hoover-city-council-to-consider-2027-budget-on-monday-sept-2/", "placement": "", "views": 0}, {"id": "a1019", "slug": "nasro-launches-national-partnership-092426", "title": "Hoover-based NASRO launches national partnership to connect school resource officers with community help", "dek": "A Hoover organization that trains school resource officers across the country is leading a new national effort aimed at getting help to students and families who need it.", "section": "news", "subsection": "", "author": "Staff", "date": "2026-09-26T21:44:00", "image": "img/19.jpg", "caption": "Hoover-based NASRO launches national partnership to connect school resource officers with community help. Photo courtesy of David Bannister.", "credit": "Photo courtesy of David Bannister", "status": "published", "body": [["p", "1 of 3"], ["p", "2 of 3"], ["p", "3 of 3"], ["p", "A Hoover organization that trains school resource officers across the country is leading a new national effort aimed at getting help to students and families who need it."], ["p", "The National Association of School Resource Officers, headquartered on Valleydale Road in Hoover, announced Tuesday a three-year partnership with the Sandlin Foundation for Kids & Kindness and Neighborhood Bridges. The program is built to give SROs and school administrators a way to flag unmet needs, from shoes and groceries to winter coats, school supplies and transportation, and post them on an online platform where local residents, businesses and organizations can respond."], ["p", "NASRO, founded in 1991, provides training and best-practice guidance for school-based law enforcement officers, school administrators and school safety professionals. Its model casts the SRO in three roles: law enforcement officer, public safety educator and informal counselor and mentor."], ["p", "\"School Resource Officers build relationships every day with students, educators and families,\" said Mo Canady, executive director of NASRO. \"This partnership creates another avenue for communities to support their students while strengthening the relationships that make our schools and communities stronger.\""], ["p", "The initiative begins with a 90-day pilot during the 2026-27 school year, starting with five NASRO locations and up to 20 combined Neighborhood Bridges and NASRO sites. The organizations plan to use the pilot to count the number and types of needs identified, track how quickly communities fill them, gather feedback from officers and administrators and adjust the technology and training before a wider rollout."], ["p", "Neighborhood Bridges, a charitable organization that runs the technology platform, will build, train and support the system for participating communities. Under the arrangement, giving stays within the community where the need is posted."], ["p", "\"Neighborhood Bridges was built to make it incredibly easy for trusted advocates in our schools to identify a need and give their community an opportunity to respond,\" said Rick Bannister of Neighborhood Bridges. \"School Resource Officers are already on the front lines building relationships with students and families. This partnership gives them another tool to help. Most importantly, 100% of local giving stays in that community and passes through to the kids and families who need it.\""], ["p", "NASRO will handle national engagement with its membership, help identify participating communities and promote the program through its conferences and publications. The Sandlin Foundation, founded by Dwight and Sandy Sandlin, is funding technology development, staffing, training, implementation and travel."], ["p", "\"This is exactly the type of collaboration we hoped the Sandlin Foundation could help create,\" said Dwight Sandlin, founder of the Sandlin Foundation for Kids & Kindness. \"We want to bring great organizations together, remove barriers, provide resources and help multiply their impact. When an SRO sees a child who needs help, we want that officer to have a way to turn that need into action.\""], ["p", "NASRO's offices are located at 2020 Valleydale Road, Suite 207A."]], "source": "https://hooversun.com/news/nasro-launches-national-partnership-092426/", "placement": "", "views": 0}, {"id": "a1020", "slug": "hoover-knoxville-football-recap-092526", "title": "Bucs stunned by late Hail Mary", "dek": "Hoover fell to Knoxville Catholic on the final play Friday night.", "section": "sports", "subsection": "Hoover", "author": "Kyle Parmley", "date": "2026-09-26T18:24:05", "image": "img/20.jpg", "caption": "Hoover wide receiver Jordon Ward (5) is brought down by his jersey during a game between Hoover High School and Knoxville Catholic High School on Friday, September 25, 2026, at the Hoover Met. Photo by Barry Stephenson", "credit": "", "status": "published", "body": [["p", "1 of 37"], ["p", "2 of 37"], ["p", "3 of 37"], ["p", "4 of 37"], ["p", "5 of 37"], ["p", "6 of 37"], ["p", "7 of 37"], ["p", "8 of 37"], ["p", "9 of 37"], ["p", "10 of 37"], ["p", "11 of 37"], ["p", "12 of 37"], ["p", "13 of 37"], ["p", "14 of 37"], ["p", "15 of 37"], ["p", "16 of 37"], ["p", "17 of 37"], ["p", "18 of 37"], ["p", "19 of 37"], ["p", "20 of 37"], ["p", "21 of 37"], ["p", "22 of 37"], ["p", "23 of 37"], ["p", "24 of 37"], ["p", "25 of 37"], ["p", "26 of 37"], ["p", "27 of 37"], ["p", "28 of 37"], ["p", "29 of 37"], ["p", "30 of 37"], ["p", "31 of 37"], ["p", "32 of 37"], ["p", "33 of 37"], ["p", "34 of 37"], ["p", "35 of 37"], ["p", "36 of 37"], ["p", "37 of 37"], ["p", "HOOVER — The Hoover High School football team appeared to have done enough to secure a hard-fought victory Friday night.Then, when the clock hit zero, Knoxville Catholic (Tenn.) pulled off the improbable."], ["p", "The Irish stunned the Buccaneers with a touchdown on the final play of the game, as Braylen Gibbs came down with a desperation pass in the back of the end zone to give Knoxville Catholic a 20-17 victory in the non-region affair at the Hoover Met."], ["p", "Hoover (3-3) had taken a 17-14 lead into the fourth quarter and appeared to have the game under control after its defense forced a turnover on downs with less than five minutes remaining."], ["p", "The Bucs then nearly put the game away."], ["p", "Kaleb Freeman connected with Anderson Clark for a first down before Malik Boggan broke loose for what appeared to be a clinching 20-yard touchdown run. But the play was negated by a holding penalty."], ["p", "Hoover eventually turned the ball over on downs after going for it on fourth-and-15. Ja'Myreion Dickerson nearly made the gamble pay off, making a tremendous effort on a toss toward the back right corner of the end zone, but he was unable to stay in bounds."], ["p", "With only 29 seconds remaining, Knoxville Catholic (5-1) suddenly had one last chance."], ["p", "Quarterback Mack Bartholomew escaped pressure and found Brayden Howard for a 45-yard gain. The play moved Knoxville Catholic to within 30 yards of the end zone with 10 seconds remaining."], ["p", "After the first stab at the end zone fell incomplete, it set up one final, improbable snap."], ["p", "Bartholomew started to his left before circling back toward the right side of the field. With pressure bearing down, he launched a pass toward the back of the end zone."], ["p", "Five players — three Bucs and two Irishmen — leaped into the air with a chance at the ball."], ["p", "Gibbs came down with it."], ["p", "The University of Alabama commit secured the ball and held on as he was taken to the ground, surviving the ensuing wrestling match long enough to make the touchdown official and send the visitors’ bench into a frenzy."], ["p", "The final play overshadowed what had been a back-and-forth game throughout."], ["p", "“I am heartbroken for the guys,” Hoover head coach Chip English said. “It’s tough losing like that, but we have to play better. The countless penalties that we did to ourselves, we cannot do that and win. Give them credit for making a play, but we have to do better, change some things up and figure things out.”"], ["p", "Knoxville Catholic opened the scoring after Freeman was pressured while scrambling and lost the ball, allowing Liam Gray to scoop it up and walk in for a 5-yard fumble recovery touchdown with 4:45 left in the first quarter."], ["p", "Hoover answered with a 12-play, 77-yard drive, capped by Freeman’s 20-yard touchdown run early in the second quarter. Freeman trucked through a defender at the goal line to tie the game at 7-7."], ["p", "DJ Waluyn intercepted Bartholomew on the first play of the ensuing drive, setting up Hoover’s go-ahead touchdown. Jordan Williams carried three times for 38 yards on the drive, finishing it with a 7-yard touchdown run out of the Wildcat."], ["p", "Knoxville Catholic answered before halftime when Gibbs made an acrobatic catch in the corner of the end zone with 29 seconds remaining, tying the game at 14-14."], ["p", "Hoover regained the lead in the third quarter after a 17-play drive stalled near the goal line, settling for Steele Witschy’s 25-yard field goal."], ["p", "The Bucs had another opportunity early in the fourth quarter after a short Knoxville Catholic punt and kick-catch interference gave Hoover the ball at the Irish 20. But a false start and sack pushed the Bucs backward, and Witschy’s 45-yard field-goal attempt fell short and left."], ["p", "Hoover then turned to its defense, which forced Knoxville Catholic into a fourth-and-9 after the Irish jumped early on fourth-and-4. KJ Wright tracked down Bartholomew for a sack, seemingly putting the Bucs in position to close out the victory."], ["p", "Instead, Knoxville Catholic got that one final chance, and made it count."], ["p", "Hoover’s difficult schedule continues next Friday when undefeated Thompson visits the Hoover Met."], ["p", "Thank you to Southlake Orthopaedics for sponsoring our coverage of Hoover football this season."], ["p", "XO Stats contributed to this report."]], "source": "https://hooversun.com/sports/hoover-knoxville-football-recap-092526/", "placement": "", "views": 0}, {"id": "a1021", "slug": "church-on-the-bluff-honors-pastor-tony-barber-for-20-years-o", "title": "Church on the Bluff honors Pastor Tony Barber for 20 years of leadership", "dek": "Church on the Bluff celebrated Pastor Tony Barber's 20th anniversary of leadership Sept. 13 with a worship service, anniversary program and luncheon.", "section": "news", "subsection": "", "author": "Staff", "date": "2026-09-25T10:36:57", "image": "img/21.jpg", "caption": "Church on the Bluff Pastor Tony Barber is presented with a letter of recognition from Gov. Kay Ivey by Minister of Music Duane Terpo.", "credit": "Photo courtesy of Church on the Bluff", "status": "published", "body": [["p", "Church on the Bluff celebrated Pastor Tony Barber's 20th anniversary of leadership with a special service and program Sept. 13."], ["p", "Congregants and friends gathered for a morning worship service followed by an anniversary program and fellowship luncheon honoring Barber's two decades of ministry at the Hoover church."], ["p", "During the program, Barber received a special presentation from the Birmingham Metro Baptist Association as well as letters of recognition from Hoover Mayor Nick Derzis and Gov. Kay Ivey."], ["p", "\"Pastor Tony has been a cornerstone of our church family for twenty years,\" said Duane Terpo, minister of music at Church on the Bluff. \"His heart for ministry, unwavering faith and deep commitment to serving others have left an indelible mark on all of us.\""], ["p", "During his 20 years at Church on the Bluff, Barber has led community initiatives and provided spiritual guidance to families in the congregation. His wife, Angie Barber, also serves the church through its children's ministry."], ["p", "Following the anniversary program, church members and guests gathered for a luncheon in the fellowship hall, where attendees shared stories and congratulated Barber on the milestone."]], "source": "https://hooversun.com/news/church-on-the-bluff-honors-pastor-tony-barber-for-20-years-o/", "placement": "", "views": 0}, {"id": "a1022", "slug": "hoover-open-houses-september-26-27", "title": "Hoover open houses September 26-27", "dek": "Looking for a home in Hoover? Check out some open houses happening this weekend.", "section": "business", "subsection": "", "author": "Staff", "date": "2026-09-25T10:19:11", "image": "img/22.jpg", "caption": "", "credit": "Photo courtesy of Zillow", "status": "published", "body": [["p", "2187 Rocky Ridge Road"], ["p", "Hoover"], ["h", "Mls#: 21465101"], ["p", "3 bedrooms/1 baths/1,329 square feet"], ["p", "$299,900"], ["p", "Joshua Ehmke: 205-999-4281, Keller Williams Realty Vestavia"], ["p", "Sunday, September 27, 2026, 2-4 p.m."], ["p", "3337 Shallowford Road"], ["p", "Birmingham"], ["h", "Mls#: 21465566"], ["p", "4 bedrooms/3 baths/1,790 square feet"], ["p", "$439,900"], ["p", "Scott Heath: 205-532-3882, ARC Realty Vestavia"], ["p", "Sunday, September 27, 2026, 2-4 p.m."], ["p", "2339 Abbeyglen Circle"], ["p", "Hoover"], ["h", "Mls#: 21464561"], ["p", "4 bedrooms/3 baths/2,641 square feet"], ["p", "$489,999"], ["p", "Kelley Sheffield: 205-702-5063, Keller Williams"], ["p", "Sunday, September 27, 2026, 2-4 p.m."], ["p", "5651 Brocks Cove"], ["p", "Hoover"], ["h", "Mls#: 21462901"], ["p", "5 bedrooms/4 baths/4,081 square feet"], ["p", "$1,275,000"], ["p", "Connor Hurst: 256-267-9097, RealtySouth Chelsea Branch"], ["p", "Sunday, September 27, 2026, 2-4 p.m."], ["p", "4589 McGill Terrace"], ["p", "Hoover"], ["h", "Mls#: 21465147"], ["p", "5 bedrooms/6 baths/5,130 square feet"], ["p", "$1,175,000"], ["p", "Jordan Hosey: 205-213-2633, HBH Realty Group at The Real Broker LLC"], ["p", "Sunday, September 27, 2026, 2-4 p.m."]], "source": "https://hooversun.com/businesses/hoover-open-houses-september-26-27/", "placement": "", "views": 0}, {"id": "a1023", "slug": "football-friday-092526", "title": "Football Friday: Bucs playing at home", "dek": "High school football in Hoover continues Friday night.", "section": "sports", "subsection": "Hoover", "author": "Kyle Parmley", "date": "2026-09-25T09:19:00", "image": "img/23.jpg", "caption": "Under the Lights football gameday.", "credit": "", "status": "published", "body": [["p", "Friday night means gameday for the local high school football teams, and Under the Lights is back to cover Football Friday."], ["p", "Hoover is back in action Friday night, hosting Knoxville Catholic out of Tennessee in a non-region matchup. Spain Park is taking an open date."], ["p", "For updates throughout Friday night and all season, follow sports editor Kyle Parmley on X (@KyleParmley) and the Under the Lights social media accounts (Facebook and X)."], ["p", "Be sure you're subscribed to the Under the Lights email newsletter, where you get the updated each weekend on the scores and news from the Friday night action. Subscribe at this link."], ["p", "Thank you to Southlake Orthopaedics for sponsoring our coverage of Hoover football this season."], ["h", "Hoover (3-2) vs. Knoxville Catholic (Tenn.) [4-1]"], ["li", "Date: Friday, Sept. 25"], ["li", "Time: 7 p.m."], ["li", "Location: Hoover Met"], ["p", "Last week: Hoover beat Oak Mountain 59-13; Knoxville Catholic fell to Montgomery Bell Academy 35-7."], ["p", "What to watch: Hoover's defense got in on the scoring against Oak Mountain, with DJ Waluyn returning an interception for a touchdown. The Bucs' offense was rolling, too, piling up 602 total yards with eight different players carrying the ball. Knoxville Catholic suffered its first loss of the season in a high-profile matchup with previously unbeaten Montgomery Bell Academy. Both teams will look to impress in a matchup of high-profile programs."], ["p", "Last meeting: This will be the first meeting between Hoover and Knoxville Catholic."], ["p", "Next week: Hoover hosts Thompson, while Knoxville Catholic hosts Ensworth."]], "source": "https://hooversun.com/sports/football-friday-092526/", "placement": "", "views": 0}, {"id": "a1024", "slug": "birmingham-bash-092326", "title": "Birmingham Bash brings more than 400 youth soccer teams to area fields this weekend", "dek": "More than 400 youth soccer teams from 10 states will spread across fields in Shelby County and the southern Birmingham area this weekend for the 2026 Birmingham Bash.", "section": "sports", "subsection": "", "author": "Staff", "date": "2026-09-24T07:59:44", "image": "img/24.jpg", "caption": "Logo courtesy of Birmingham United.", "credit": "Logo courtesy of Birmingham United", "status": "published", "body": [["p", "More than 400 youth soccer teams from 10 states will spread across fields in Shelby County and the southern Birmingham area this weekend for the 2026 Birmingham Bash."], ["p", "The tournament, hosted by Birmingham United Soccer Association/Alabama FC, runs Friday through Sunday, Sept. 25-27, at sites in Alabaster, Calera, Hoover, Dunnavant Valley and Mountain Brook. Organizers said the field of teams set a record for the event and makes it the largest single-weekend youth sporting event in Alabama this year."], ["p", "More than 6,000 players are expected to compete, with organizers estimating another 18,000 to 22,000 family members and fans in the stands. BUSA projects the weekend will generate about $9.6 million in local economic impact through hotel stays, restaurants and shopping."], ["p", "Divisions run from under-8 through under-19 for boys and girls, with teams from Alabama, Georgia, Tennessee, Mississippi and Florida among the entries. Venues include Dunnavant Valley (formerly Sports Blast), Rathmell Sports Complex, Hoover Met Turf Complex, Mountain Brook High School, Municipal Park, Veterans Park, Eagle Sports Complex and Heardmont Park."], ["p", "The Hoover Met Turf Complex is a primary site across nearly every age group. Hoover Soccer Club has teams entered in the U15 girls, U15 boys, U16 boys and U17 boys divisions, and Barca Academy-Hoover has entries from U8 through U12."], ["p", "BUSA/Alabama FC fields more than 9,800 players ages 3 to 19 annually and is the state's largest soccer organization. Schedules and more information are available at birminghamunited.com."]], "source": "https://hooversun.com/sports/birmingham-bash-092326/", "placement": "", "views": 0}, {"id": "a1025", "slug": "volleyball-update-092426", "title": "Kyes breaks career digs record at Spain Park", "dek": "Here's a weekly update on Hoover and Spain Park's volleyball teams.", "section": "sports", "subsection": "", "author": "Kyle Parmley", "date": "2026-09-24T05:59:53", "image": "img/25.jpg", "caption": "Spain Park's Camdyn Kyes (3) waits for the ball during action at the Juanita Boddie Tournament at the Finley Center in Hoover, AL on Fri., Aug. 21, 2026. Photo by David Leong.", "credit": "Photo by David Leong", "status": "published", "body": [["p", "Spain Park High School's volleyball team put together a busy week, with a road loss to open things, a dominant run through the HeffStrong Tournament, and a road win over Thompson to close it out."], ["p", "The Jaguars went 8-2 over the stretch. Spain Park opened Thursday with a loss at Jasper, then rattled off seven wins over the HeffStrong Tournament weekend, beating West Blocton, Lipscomb Academy, Clay-Chalkville, West Morgan, Muscle Shoals, Homewood and Houston, with their only loss of the tournament coming against Spanish Fort. Spain Park closed the week with a 3-1 win over Thompson on Tuesday."], ["p", "Camdyn Kyes highlighted the stretch by breaking the school's career digs record, previously held by Audrey Rothman, and now stands at 1,345 and counting."], ["p", "Peyton Harrington led the way with 98 kills, 56 digs and 12 aces. Kyes added 91 digs, 22 assists and 13 aces. Chloe Shumate contributed 94 kills and 12 blocks, Sarah Latham added 45 kills and 19 blocks, and setter Lynlee Franks ran the offense with 108 assists and 28 digs."], ["p", "Spain Park is at Prattville on Sept. 24 and Enterprise on Sept. 26."], ["p", "Elsewhere, Hoover had a mixed week, falling to Auburn 3-0 on Sept. 17 before going 3-1 at a tournament in Panama City, Florida, beating Arnold, Wakulla and Grace Christian Academy before falling to FSUHS. Hoover then dropped a road match at Hewitt-Trussville 3-1 on Sept. 22."], ["p", "Hoover is at Mountain Brook on Thursday before hosting Vestavia Hills on Sept. 29."]], "source": "https://hooversun.com/sports/volleyball-update-092426/", "placement": "", "views": 0}, {"id": "a1026", "slug": "aswa-poll-092326", "title": "Bucs rise a couple spots in ASWA poll", "dek": "This week's Alabama Sports Writers Association rankings are out.", "section": "sports", "subsection": "Hoover", "author": "Kyle Parmley", "date": "2026-09-24T02:54:46", "image": "img/26.jpg", "caption": "Hoover TE Anderson Clark (10) defends against Oak Mountain LB Aiden Molette (11) during a game between Hoover and Oak Mountain on September 18, 2026  at Heardmont Park in Birmingham, AL. Photo by Todd Lester", "credit": "Photo by Todd Lester", "status": "published", "body": [["p", "The Alabama Sports Writers Association released its latest high school football poll Wednesday morning."], ["p", "Hoover moved up to No. 7 in Class 6A, up from No. 9 a week ago, after a 59-13 win over Oak Mountain. The Bucs host Knoxville Catholic (Tenn.) this week in a non-region game."], ["p", "Spain Park dropped to No. 10, down from No. 7, after falling 30-7 to Vestavia Hills, and the Jaguars have an open date this week."], ["p", "The full Class 6A poll:"], ["h", "Class 6A"], ["p", "Team (first-place); W-L; Pts"], ["p", "1. Thompson (20); 5-0; 240"], ["p", "2. Central-Phenix City; 4-1; 172"], ["p", "3. Prattville; 5-0; 167"], ["p", "4. Vestavia Hills; 4-1; 141"], ["p", "5. Daphne; 4-1; 84"], ["p", "6. Hewitt-Trussville; 3-2; 83"], ["p", "7. Hoover; 3-2; 77"], ["p", "8. Auburn; 3-2; 60"], ["p", "9. Opelika; 2-2; 40"], ["p", "10. Spain Park; 3-2; 34"], ["p", "Others receiving votes: James Clemens (4-1) 20, Fairhope (4-1) 16, Sparkman (4-1) 3, Carver-Montgomery (3-2) 2, Enterprise (3-2) 1."], ["p", "Thank you to Southlake Orthopaedics for sponsoring our coverage of Hoover football this season."]], "source": "https://hooversun.com/sports/aswa-poll-092326/", "placement": "", "views": 0}, {"id": "a1027", "slug": "hoover-mom-business-owner-to-compete-for-mrs-america", "title": "Hoover mom, business owner to compete for Mrs. America", "dek": "Hoover resident and business owner Katie Guerin won Mrs. Alabama America 2026 and is heading to Las Vegas to compete for Mrs. America.", "section": "people", "subsection": "", "author": "Lauren H. Dowdle", "date": "2026-09-23T20:03:00", "image": "img/27.jpg", "caption": "Right: Katie Guerin won Mrs. Alabama America in June and will now participate in Mrs. America in Las Vegas.", "credit": "", "status": "published", "body": [["p", "Not only does Katie Guerin wear many hats — from mother and wife to business owner and community volunteer — but she also dons a variety of tiaras."], ["p", "A Hoover resident, Guerin has been competing in pageant scholarship programs across Alabama, Georgia and Florida since she was 12 years old. After aging out of teen pageants, she moved into the adult category and won titles like Ms. Alabama United States and Ms. Woman Florida United States."], ["p", "When she reached 30, she decided to hang up her crown and focus on getting married, starting a family and growing her career as a hair stylist. She’s now married with two daughters — Minnie, 4, and Rosie, 2 — and owns Foil Salon at 260 Old Town Road in Vestavia Hills behind the bowling alley. Opened in 2022, the salon offers a variety of hair services and has a nail technician and massage therapist."], ["p", "But a decade after her last pageant, she decided to slip back into an evening gown and compete for Mrs. Alabama America. She came in as the second alternate in 2025 and said she wanted to work even harder this year. In June, Guerin took home the title of Mrs. Alabama America 2026."], ["p", "“When I won, Minnie could hardly stand it and jumped on the stage and gave me a big kiss. That was the best feeling,” she said. “I want to show my girls that dreams don’t have an expiration date. Just because I’m a mommy and married doesn’t mean I have to stop my dreams and plans.”"], ["p", "During her reign as Mrs. Alabama America, Guerin will continue her work in the community with nonprofits like The Lovelady Center, Ronald McDonald House, Go Red for Women, Breast Cancer Research Foundation, and her organization, The Umbrella Foundation. Under her foundation, she’s working to create a scholarship program for girls ages 4 to 18 called Little Miss Birmingham. She hopes to start the program in early 2027."], ["p", "Throughout this experience, she said the best part has been doing it with her daughters."], ["p", "“I want them to see the importance of giving back and that the smallest hands can make the biggest difference,” Guerin said. “Philanthropy is literally my passion. It’s what God sent me here to do.”"], ["p", "With the support of her daughters and husband, Clay, Guerin was set to compete for the title of Mrs. America during the program’s 50th anniversary Aug. 25 through Sept. 3 in Las Vegas. The event will also include Miss for America Strong and Mrs. American."], ["p", "Having previously helped with the hair and makeup at Mrs. America, Guerin has come full circle now that she will be the one taking the stage. While she’s preparing to compete, Guerin said she remembers the event is about more than bringing home the crown."], ["p", "“If you focus too much on winning, you miss out on the experience as a whole. I’m looking forward to being with the other women and enjoying the shows, dinners and new friendships,” she said. “Every single woman is significantly different, incredibly talented and has achievements on another level.”"], ["p", "The Mrs. America competition will be broadcast by the Mrs. America Presents social media accounts."]], "source": "https://hooversun.com/peopleplaces/hoover-mom-business-owner-to-compete-for-mrs-america/", "placement": "", "views": 0}, {"id": "a1028", "slug": "hoover-school-board-approves-275-million-budget-for-2027", "title": "Hoover school board approves $275 million budget for 2027", "dek": "The budget includes $20 million for capital projects at various schools.", "section": "schools", "subsection": "", "author": "Jon Anderson", "date": "2026-09-23T08:53:00", "image": "img/28.jpg", "caption": "The Hoover Board of Education meets to consider its 2027 budget on Tuesday, Sept. 8, 2026.", "credit": "Photo by Jon Anderson", "status": "published", "body": [["p", "The Hoover school board recently approved a $275 million budget for fiscal 2027, representing an 1% increase from the 2026 budget approved a year ago."], ["p", "That includes $225 million in spending from the general fund, up from $205 million in 2026, and $20 million in projected capital projects. Even though the district’s enrollment is declining slightly, the number of personnel is increasing as student needs increase, district officials say."], ["p", "The school district this year has added 12 more exceptional education aides, six more exceptional education teachers, four enrichment teachers, two part-time interventionists and one office secretary, Chief School Financial Officer Melynda Buck said."], ["p", "Also, personnel costs have increased with the 2% raise for school system employees mandated by the state Legislature, step raises and increased costs for health insurance and retiree benefits, Buck said. About 73% of the district’s general fund expenditures are for salaries and benefits, she said."], ["h", "Capital Projects"], ["p", "Capital project funding included in the 2027 budget include:"], ["li", "$2.75 million for roofing projects at multiple schools"], ["li", "$2.5 million for heating, ventilation and air conditioning improvements"], ["li", "$2.2 million for new kitchen hoods at Hoover and Spain Park high schools"], ["li", "$2.3 million for various athletic upgrades at Greystone Elementary, Berry and Simmons middle schools and Spain Park High"], ["li", "$1.28 million for Spain Park High School soccer field upgrades"], ["li", "$1 million for renovations to the central office boardroom"], ["li", "$1 million for bathroom renovations, flooring upgrades and disability accommodations at Berry Middle School"], ["li", "$1 million for Hoover High School turf replacement and track resurfacing"], ["li", "$900,000 for six new buses"], ["li", "$700,000 for playground upgrades at Bluff Park, South Shades Crest and Trace Crossings elementary schools"], ["li", "$600,000 for parking lot improvement at Rocky Ridge Elementary"], ["p", "Between fall 2024 and fall 2025, the Hoover school system’s enrollment dropped by 33 students to 13,289, records show."], ["h", "Special Education"], ["p", "But the number of students with physical, cognitive and learning disabilities continues to increase, and so does the cost for those services, Buck said. This year, the district has 1,869 students with disabilities, up by 137 students from last year, Buck said. The school district expects to spend $46 million on special education services this year, up from $36.2 million last year, $30 million two years ago and $25.2 million three years ago, she said."], ["p", "Forty-nine years ago, the federal government pledged to cover 40% of the total cost of special education services, but the highest it has ever funded for Hoover is 18% in 2005, Buck said. For 2027, the percentage is 12%, she said."], ["p", "“It is a hot topic across all districts,” Buck said."], ["p", "Claire Jones-Moore, the district’s exceptional education director, this year was able to obtain $726,600 in grants to supplement the cost of outside professional services, Buck said."], ["p", "Hoover now has seven Title 1 schools, which means those schools have at least 40% of their students qualify for free or reduced-price meals due to low family income, Buck said. Those schools are Green Valley, Gwin, Rocky Ridge, Shades Mountain, Trace Crossings and Riverchase elementary schools and Simmons Middle School."], ["p", "Districtwide, Hoover has 4,274 students who qualify for free and reduced-price meals, which represent 32% of the total student population — down from 4,526 students (or 34%) last year, Buck said."], ["p", "The school district plans to spend $13.1 million for its child nutrition program this year, up from $11.8 million in the 2026 budget. Food costs continue to increase. The revenue to support that will include almost $4 million from the federal government, $5.2 million from food sales and $3.9 million from other sources, school system records show."], ["p", "The Hoover school district plans to spend $9.9 million for transportation in fiscal 2027, up from $8.1 million the year before. The school system has 98 drivers driving 320 bus routes with 5,309 stops this year, Buck said. Nineteen of those drivers are also teachers, she said."], ["h", "School System Debt"], ["p", "The school board’s debt payments drop this year from $13.3 million to $10.1 million, including $6 million toward principal and $4.1 million in interest. The school district’s remaining principal debt at the end of the fiscal year is estimated to be $105.6 million, but principal and interest payments total $143.9 million through 2040."], ["p", "Superintendent Kevin Maddox, who came to Hoover three years ago, has said he is very impressed that the Hoover school board has been able to fund so many capital projects without taking on any new debt since 2007."], ["p", "Those projects have included a 32-classroom addition at Hoover High School in 2011, a new Hoover High band room in 2017, turf and track renovations at both high schools, various HVAC and roofing projects, the renovation of the former Riverchase Middle School to become the Riverchase Career Connection Center in 2019, a 13-classroom addition at Berry Middle School in 2021, renovation of part of the old Bluff Park Elementary School to become a student services building, a performing arts center at Hoover High, athletic field upgrades at Hoover and Spain high schools, 69 new buses from 2020 to 2024, numerous playground and elevator upgrades, the purchase and renovation of a new operations building in the Riverchase Office Park, renovations of the theaters at both high schools, and new athletic storage areas and restrooms at Berry and Bumpus middle schools."], ["h", "Revenues"], ["p", "Total revenues for 2027 are expected to be $267 million, including $237 million in the general fund, $21.4 million in the special revenue fund, $5.1 million in the capital projects fund and $3.6 million in non-public school funds taken in by individual schools."], ["p", "Of that $267 million, $142 million comes from county and city sources while $109 million comes from the state, $15 million comes from the federal government and $430,000 comes from other sources. Hoover employs and pays 100% of the salaries and benefits for 265 of its certified employees because the district wants to increase its staffing levels beyond the state-approved amount. That includes 237 teachers, 13.5 counselors, 10.5 assistant principals, one librarian and three additional positions, records show."], ["p", "Buck noted that the Legislature since 2018 has been distributing “advancement in technology” funding to school systems that can be used for capital projects, but the Legislature may be phasing that money out in the near future. Hoover schools received $13.2 million in “advancement in technology” funds for fiscal 2025, $14.7 million for fiscal 2026 and $10.4 million for fiscal 2027, she said."], ["p", "Hoover school officials expect to begin fiscal 2027 with $143 million in the general fund and end the fiscal year on Sept. 30, 2027, with $140 million in the general fund, which represents almost seven months worth of expenses. Buck said the desired general fund minimum typically is about five months of expenses, or $100.6 million, so the district should easily maintain that, she said."], ["p", "However, if the school district were to build a new elementary school, that likely would cost an estimated $55 million, which would leave the district with only three or four months’ worth of reserves, Buck said."], ["h", "Looking Forward"], ["p", "Buck said it’s important to share with state legislators the importance of keeping public funds in public schools and increased costs that schools are facing in regard to special education programs, mental health and school nurses."], ["p", "She also encouraged the school board to share with legislators the difficulty of recruiting and retaining highly qualified employees and to consider making financial allocations for nurses based on enrollment and allocations for custodians based on the size of facilities. It also would be helpful to have the Legislature fund a math interventionist for every school, she said."], ["p", "Buck said she hopes school officials can next year look at increasing compensation for school support staff."], ["p", "School board President Alan Paquette said the school district is responsible for about $3 billion worth of real estate."], ["p", "He thinks the school district does a really good job of maintaining those properties, but he thinks there is a lot of savings that can be found when it comes to utility costs, whether by using photo cells, continued conversion to LED lights, implementing more energy management systems or better identifying water leaks and repairing them more quickly."], ["p", "“I think there is hundreds of thousands of dollars that we can find in savings,” he said."]], "source": "https://hooversun.com/schools/hoover-school-board-approves-275-million-budget-for-2027/", "placement": "", "views": 0}, {"id": "a1029", "slug": "week-6-football-preview-092326", "title": "Week 6 Football Preview: Bucs play out-of-state foe", "dek": "Hoover football is back in action Friday night.", "section": "sports", "subsection": "Hoover", "author": "Kyle Parmley", "date": "2026-09-23T08:37:00", "image": "img/29.jpg", "caption": "Hoover QB Kaleb Freeman (7) runs the football during a game between Hoover and Oak Mountain on September 18, 2026  at Heardmont Park in Birmingham, AL. Photo by Todd Lester", "credit": "Photo by Todd Lester", "status": "published", "body": [["p", "Week 5 is in the books, and the Under the Lights teams are back at it for Week 6. Most teams are taking an open date, but a few teams are playing a non-region opponent at the season's midway point."], ["p", "Here’s a quick look at the Week 6 slate. Be sure to follow Under the Lights on X and Facebook for updates all season long. Get all of our coverage in your inbox each Saturday morning as well."], ["p", "Thank you to Gunn Dermatology for sponsoring our coverage of Mountain Brook football this season. Visit their two locations in Mountain Brook."], ["h", "Hoover (3-2) vs. Knoxville Catholic (Tenn.) [4-1]"], ["li", "Date: Friday, Sept. 25"], ["li", "Time: 7 p.m."], ["li", "Location: Hoover Met"], ["p", "Last week: Hoover beat Oak Mountain 59-13; Knoxville Catholic fell to Montgomery Bell Academy 35-7."], ["p", "What to watch: Hoover's defense got in on the scoring against Oak Mountain, with DJ Waluyn returning an interception for a touchdown. The Bucs' offense was rolling, too, piling up 602 total yards with eight different players carrying the ball. Knoxville Catholic suffered its first loss of the season in a high-profile matchup with previously unbeaten Montgomery Bell Academy. Both teams will look to impress in a matchup of high-profile programs."], ["p", "Last meeting: This will be the first meeting between Hoover and Knoxville Catholic."], ["p", "Next week: Hoover hosts Thompson, while Knoxville Catholic hosts Ensworth."], ["h", "Briarwood (5-0) vs. Montgomery Catholic (4-1)"], ["li", "Date: Friday, Sept. 25"], ["li", "Time: 7 p.m."], ["li", "Location: Lions Pride Stadium"], ["p", "Last week: Briarwood beat Madison Academy 49-14; Montgomery Catholic beat Glenwood 38-15."], ["p", "What to watch: Briarwood leaned almost entirely on the ground game against Madison Academy, piling up 291 rushing yards while attempting just 12 passes, with Jamison Barnes running for 144 yards and two touchdowns. Montgomery Catholic enters unbeaten in region play and riding a three-game winning streak of its own. It's an out-of-area, non-region test for the Lions as they head into the second half of the season still unbeaten."], ["p", "Last meeting: Briarwood and Montgomery Catholic have never met."], ["p", "Next week: Briarwood travels to St. John Paul II, while Montgomery Catholic hosts St. Paul’s."], ["h", "Game of the Week"], ["h", "Mountain Brook (3-2) vs. Oxford (4-1)"], ["li", "Date: Friday, Sept. 25"], ["li", "Time: 7 p.m."], ["li", "Location: Spartan Stadium"], ["p", "Last week: Mountain Brook beat Chilton County 43-13; Oxford fell to Clay-Chalkville 49-14."], ["p", "What to watch: Mountain Brook piled up 375 total yards against Chilton County, with Butler Teague running for 130 yards and two touchdowns. Oxford was held to negative rushing yardage in its first loss of the season, a defeat to defending state champion Clay-Chalkville that snapped a four-game win streak. Mountain Brook will look to make it three straight victories as it works to build momentum in a non-region matchup."], ["p", "Last meeting: Mountain Brook defeated Oxford 42-14 in 2025. The two teams have split four previous meetings."], ["p", "Next week: Mountain Brook hosts Ramsay, while Oxford has an open date."], ["p", "Historical data courtesy of AHSFHS.org."]], "source": "https://hooversun.com/sports/week-6-football-preview-092326/", "placement": "", "views": 0}], "events": [{"id": "e100", "title": "Shades Crest Arts And Crafts Fair", "date": "2026-10-03", "when": "Saturday, Oct. 3, 9 a.m. to 3 p.m.", "where": "Shades Crest Baptist Church, Fellowship Hall, 452 Park Ave., Hoover", "cost": "", "details": "Shop locally made art and handmade goods at the annual Shades Crest Arts and Crafts Fair. The event brings together artists and crafters for a day of shopping, food and activities at Shades Crest Baptist Church. The fair coincides with the nearby Bluff Park Art Show, making the area a destination for art lovers throughout the day. Proceeds from exhibitor table rentals and food sales will benefit Lift Up the Vulnerable, an organization working to protect and empower vulnerable children and women.", "contact": "205-822-1360", "link": "shadescrest.org", "status": "approved", "source": "Events guide"}, {"id": "e104", "title": "Grace on the Bluff", "date": "2026-10-03", "when": "Saturday, Oct. 3, 8-11 a.m.", "where": "Church on the Bluff, 2211 McGwier Drive, Hoover", "cost": "Free", "details": "A community yard sale where everything is free. Rain location: the church fellowship hall.", "contact": "", "link": "churchonthebluff.org", "status": "approved", "source": "Events guide"}, {"id": "e101", "title": "BHM26.2 Race Series", "date": "2026-10-04", "when": "Sunday, Oct. 4, 7 a.m. to 2 p.m.", "where": "The Finley Center at the Hoover Metropolitan Complex", "cost": "Varies by race; advance registration required.", "details": "Hit the pavement for a cause at the BHM26.2 Race Series, a full day of running and family fun benefiting Magic Moments. The event includes a marathon, half marathon, 5-person marathon relay, 10K, 5K and kids fun run, with options for runners of a variety of ages and experience levels. More than 2,000 runners participate in the annual event, which has raised more than $1 million to help bring special experiences to Alabama children facing serious medical conditions. Race day also includes a family-friendly after party with food, entertainment and a kids’ zone.", "contact": "", "link": "bhm262.com", "status": "approved", "source": "Events guide"}, {"id": "e102", "title": "Alabama Woodworkers Guild Annual Members Exhibition", "date": "2026-10-11", "when": "Oct. 11-15, during regular library hours", "where": "Hoover Public Library, 200 Municipal Drive, Hoover", "cost": "Free", "details": "Discover the artistry and craftsmanship of local woodworkers during the Alabama Woodworkers Guild Annual Members Exhibition. Handmade creations from guild members ranging from beginners to master craftsmen will be displayed throughout the Friends Gallery, Shakespeare Room and Southern Voices Gallery. The annual exhibition offers visitors a chance to see a variety of woodworking styles, techniques and projects created by talented artisans from across the area.", "contact": "205-444-7800", "link": "hooverlibrary.org", "status": "approved", "source": "Events guide"}, {"id": "e105", "title": "Taste of Hoover", "date": "2026-10-15", "when": "Thursday, Oct. 15, 5-8 p.m.", "where": "Aldridge Gardens, 3530 Lorna Road, Hoover", "cost": "Limited tickets", "details": "Food and drink samplings from local restaurants and caterers, live music and ambient lighting overlooking the gardens.", "contact": "", "link": "aldridgegardens.com", "status": "approved", "source": "Events guide"}, {"id": "e103", "title": "Étouffée Soirée With Byrd & Chase", "date": "2026-10-18", "when": "Sunday, Oct. 18, 5 p.m.", "where": "Jubilee Joe’s Cajun Seafood Restaurant, 5190 Medford Drive, Suite 114, Hoover", "cost": "", "details": "Spend a Sunday evening enjoying Cajun cuisine and live music during Étouffée Soirée at Jubilee Joe’s. Byrd & Chase will perform an acoustic mix of country, pop, blues and rock on the patio, with song requests welcome. Grab a plate of your favorite Cajun fare, settle in and enjoy an easygoing evening of food and live local music.", "contact": "205-982-7797", "link": "jubileejoes.com", "status": "approved", "source": "Events guide"}]};
